 the claimed trigger>\"] * 8\n30\t\n31\t\n32\tdef _commit():\n33\t    return subprocess.run([\"git\", \"rev-parse\", \"--short\", \"HEAD\"], cwd=ROOT, capture_output=True, text=True).stdout.strip()\n34\t\n35\t\n36\tdef new(a):\n37\t    m = NEURON.match(a.neuron)\n38\t    if not m:\n39\t        sys.exit(\"neuron must look like bonsai1/L12/N5397+ (model/layer/index and pole)\")\n40\t    cid = f\"{dt.date.today().isoformat()}-{a.handle}-{secrets.token_hex(2)}\"\n41\t    d = folder_for(a.neuron)\n42\t    d.mkdir(parents=True, exist_ok=True)\n43\t    unit = f\"L{m['L']}/N{m['n']}\"\n44\t    current = None\n45\t    rec = ROOT / \"graph\" / \"neurons\" / m[\"model\"] / f\"{d.name}.json\"\n46\t    if rec.exists():\n47\t        current = json.loads(rec.read_text(encoding=\"utf-8\")).get(\"label\")\n48\t    t = {\"contribution\": cid, \"contributor\": a.handle, \"kind\": a.kind, \"neuron\": a.neuron, \"protocol\": \"quick-8+8@1\",\n49\t         \"written\": dt.datetime.now(dt.timezone.utc).isoformat(timespec=\"seconds\"),\n50\t         **({\"qc\": {\"verdict\": a.verdict, \"label_under_test\": current}} if a.kind == \"qc\" else {}),\n51\t         \"neighbours\": [{\"unit\": unit, \"pole\": m[\"pole\"], \"label\": current if a.kind == \"qc\" and a.verdict != \"refine\" else \"<your label>\",\n52\t                         \"fire\": TEMPLATE_FIRE, \"quiet\": TEMPLATE_QUIET}],\n53\t         \"predictions\": \"<optional: what you expect, e.g. '6/8 fire, 0 near misses'>\"}\n54\t    p = d / f\"{cid}.tests.json\"\n55\t    p.write_text(json.dumps(t, ensure_ascii=False, indent=1) + \"\\n\", encoding=\"utf-8\", newline=\"\\n\")\n56\t    print(f\"wrote {p.relative_to(ROOT)}\\nFill in the label and the 16 sentences, then commit THIS FILE ALONE:\\n\"\n57\t          f\"  git add {p.relative_to(ROOT).as_posix()} && git commit -m \\\"Pre-register {a.kind} test for {a.neuron}\\\"\\n\"\n58\t          f\"then: python -m bonsai_interp.graph.play run {p.relative_to(ROOT).as_posix()}\")\n59\t\n60\t\n61\tdef run(a):\n62\t    import torch\n63\t    from bonsai_interp import explore\n64\t    from bonsai_interp.model import load\n65\t    from bonsai_interp.probe import textinv\n66\t    p = Path(a.tests_file).resolve()\n67\t    rel = p.relative_to(ROOT).as_posix()\n68\t    if subprocess.run([\"git\", \"log\", \"--format=%h\", \"-1\", \"--\", rel], cwd=ROOT, capture_output=True, text=True).stdout.strip() == \"\":\n69\t        sys.exit(f\"{rel} is not committed yet. Commit the pre-registration first, then run it.\")\n70\t    if subprocess.run([\"git\", \"diff\", \"--quiet\", \"HEAD\", \"--\", rel], cwd=ROOT).returncode != 0:\n71\t        sys.exit(f\"{rel} has uncommitted edits. A pre-registration must be run exactly as committed.\")\n72\t    t = json.loads(p.read_text(encoding=\"utf-8\"))\n73\t    if any(\"<\" in s for nb in t[\"neighbours\"] for s in nb[\"fire\"] + nb[\"quiet\"] + [nb[\"label\"]]):\n74\t        sys.exit(\"the tests file still has <placeholders>\")\n75\t    prereg = subprocess.run([\"git\", \"log\", \"--diff-filter=A\", \"--format=%h\", \"--\", rel], cwd=ROOT, capture_output=True, text=True).stdout.split()[-1]\n76\t    m = NEURON.match(t[\"neuron\"])\n77\t    torch.cuda.set_per_process_memory_fraction(0.8)\n78\t    model, tok, rec = load(m[\"model\"])\n79\t    tok.padding_side = \"right\"\n80\t    scan = explore.scan(m[\"model\"])\n81\t    tests = []\n82\t    for nb in t[\"neighbours\"]:\n83\t        L, n = map(int, nb[\"unit\"][1:].split(\"/N\"))\n84\t        pole = 0 if nb[\"pole\"] == \"+\" else 1\n85\t        pmax, omax = float(scan[\"top_val\"][L, pole, 0, n]), float(scan[\"top_val\"][L, 1 - pole, 0, n])\n86\t        ev = textinv.TextEvaluator(model, tok, rec, L, n, pmax, omax, 1.0 if pole == 0 else -1.0)\n87\t        fire, quiet = ev(nb[\"fire\"]), ev(nb[\"quiet\"])\n88\t        per = [{\"set\": s, \"i\": i, \"act\": round(r[\"act\"], 3), \"peak\": r[\"peak_token\"]} for s, rs in ((\"fire\", fire), (\"quiet\", quiet)) for i, r in enumerate(rs)]\n89\t        nf, fp = sum(r[\"act\"] >= 0.3 for r in fire), sum(r[\"act\"] >= 0.3 for r in quiet)\n90\t        tests.append({\"protocol\": t[\"protocol\"], \"tests_file\": rel, \"prereg_commit\": prereg, \"author\": a.author or t[\"contributor\"],\n91\t                      \"n_fire\": nf, \"n_false_pos\": fp, \"n_written\": [len(fire), len(quiet)], \"per_sentence\": per})\n92\t        print(f\"{nb['unit']}{nb['pole']}: fire {nf}/{len(fire)}, near misses firing {fp}/{len(quiet)} -> {'HELD' if nf >= 5 and fp <= 1 else 'FAILED'}\")\n93\t    c = {\"id\": t[\"contribution\"], \"kind\": t[\"kind\"], \"neuron\": t[\"neuron\"], \"contributor\": t[\"contributor\"],\n94\t         \"created\": dt.datetime.now(dt.timezone.utc).isoformat(timespec=\"seconds\"),\n95\t         \"recipe\": {\"toolchain_commit\": _commit(), \"command\": f\"python -m bonsai_interp.graph.play run {rel}\"},\n96\t         \"label\": t[\"neighbours\"][0][\"label\"], \"tests\": tests}\n97\t    if t[\"kind\"] == \"qc\":\n98\t        c[\"qc\"] = {\"verdict\": t[\"qc\"][\"verdict\"], \"label_under_test\": t[\"qc\"].get(\"label_under_test\")}\n99\t        if t[\"qc\"][\"verdict\"] != \"refine\":\n100\t            c.pop(\"label\")\n101\t    for k in (\"short\", \"unit_kind\", \"confidence\", \"notes\", \"roles\", \"via\"):\n102\t        if t.get(k) is not None:\n103\t            c[k] = t[k]\n104\t    out = p.with_name(p.name.replace(\".tests.json\", \".json\"))\n105\t    out.write_text(json.dumps(c, ensure_ascii=False, indent=1) + \"\\n\", encoding=\"utf-8\", newline=\"\\n\")\n106\t    print(f\"wrote {out.relative_to(ROOT)}. Next: python -m bonsai_interp.graph.fold, then commit the results in a second commit and open a PR.\")\n107\t\n108\t\n109\tdef step(a):\n110\t    import numpy as np"}]},"parent_tool_use_id":null,"session_id":"2cfd0f8a-2a52-4b9a-860e-ad1a3a409699","uuid":"64ac4561-6906-4b69-a14f-6b34655cab0c","timestamp":"2026-10-18T16:55:43.530Z","tool_use_result":{"type":"text","file":{"filePath":"~\\Documents\\survey-playtest\\bonsai-interp\\bonsai_interp\\graph\\play.py","content":"\"\"\"The contributor's command line: start a contribution, run its pre-registered test, write the results.\n\n  python -m bonsai_interp.graph.play new interpret --neuron bonsai1/L12/N5397- --handle octocat\n  python -m bonsai_interp.graph.play new qc --neuron bonsai1/L9/N3688+ --handle octocat --verdict confirm\n      -> graph/contributions/<model>/<pole folder>/<id>.tests.json   (fill in the label and sentences, then COMMIT)\n  python -m bonsai_interp.graph.play run graph/contributions/.../<id>.tests.json\n      -> <id>.json with the results (needs the GPU; commit it in a SECOND commit)\n  python -m bonsai_interp.graph.play step --neuron bonsai1/L12/N5397- [--k 4]\n      -> the strongest feeders of a pole (single-unit zeroing on its top examples): candidates for \"step out one neuron\"\n  python -m bonsai_interp.graph.play look --neuron bonsai1/L12/N5397-      top corpus examples\n  python -m bonsai_interp.graph.fold                                         refresh the derived records\n  python -m bonsai_interp.graph.play doctor                                  is this machine ready? (agents: run first)\n  python -m bonsai_interp.graph.play brief interpret --neuron <id> --handle <you>   full mission instructions for an agent\n\nThe \"run\" step follows the protocol named in the tests file (quick-8+8@1 today) and records the\ntoolchain commit, so the result can be reproduced.\n\"\"\"\nimport argparse\nimport datetime as dt\nimport json\nimport secrets\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nfrom bonsai_interp.graph.contrib import NEURON, ROOT, folder_for\n\nTEMPLATE_FIRE = [\"<sentence that should fire the pole>\"] * 8\nTEMPLATE_QUIET = [\"<near miss: same topic, without the claimed trigger>\"] * 8\n\n\ndef _commit():\n    return subprocess.run([\"git\", \"rev-parse\", \"--short\", \"HEAD\"], cwd=ROOT, capture_output=True, text=True).stdout.strip()\n\n\ndef new(a):\n    m = NEURON.match(a.neuron)\n    if not m:\n        sys.exit(\"neuron must look like bonsai1/L12/N5397+ (model/layer/index and pole)\")\n    cid = f\"{dt.date.today().isoformat()}-{a.handle}-{secrets.token_hex(2)}\"\n    d = folder_for(a.neuron)\n    d.mkdir(parents=True, exist_ok=True)\n    unit = f\"L{m['L']}/N{m['n']}\"\n    current = None\n    rec = ROOT / \"graph\" / \"neurons\" / m[\"model\"] / f\"{d.name}.json\"\n    if rec.exists():\n        current = json.loads(rec.read_text(encoding=\"utf-8\")).get(\"label\")\n    t = {\"contribution\": cid, \"contributor\": a.handle, \"kind\": a.kind, \"neuron\": a.neuron, \"protocol\": \"quick-8+8@1\",\n         \"written\": dt.datetime.now(dt.timezone.utc).isoformat(timespec=\"seconds\"),\n         **({\"qc\": {\"verdict\": a.verdict, \"label_under_test\": current}} if a.kind == \"qc\" else {}),\n         \"neighbours\": [{\"unit\": unit, \"pole\": m[\"pole\"], \"label\": current if a.kind == \"qc\" and a.verdict != \"refine\" else \"<your label>\",\n                         \"fire\": TEMPLATE_FIRE, \"quiet\": TEMPLATE_QUIET}],\n         \"predictions\": \"<optional: what you expect, e.g. '6/8 fire, 0 near misses'>\"}\n    p = d / f\"{cid}.tests.json\"\n    p.write_text(json.dumps(t, ensure_ascii=False, indent=1) + \"\\n\", encoding=\"utf-8\", newline=\"\\n\")\n    print(f\"wrote {p.relative_to(ROOT)}\\nFill in the label and the 16 sentences, then commit THIS FILE ALONE:\\n\"\n          f\"  git add {p.relative_to(ROOT).as_posix()} && git commit -m \\\"Pre-register {a.kind} test for {a.neuron}\\\"\\n\"\n          f\"then: python -m bonsai_interp.graph.play run {p.relative_to(ROOT).as_posix()}\")\n\n\ndef run(a):\n    import torch\n    from bonsai_interp import explore\n    from bonsai_interp.model import load\n    from bonsai_interp.probe import textinv\n    p = Path(a.tests_file).resolve()\n    rel = p.relative_to(ROOT).as_posix()\n    if subprocess.run([\"git\", \"log\", \"--format=%h\", \"-1\", \"--\", rel], cwd=ROOT, capture_output=True, text=True).stdout.strip() == \"\":\n        sys.exit(f\"{rel} is not committed yet. Commit the pre-registration first, then run it.\")\n    if subprocess.run([\"git\", \"diff\", \"--quiet\", \"HEAD\", \"--\", rel], cwd=ROOT).returncode != 0:\n        sys.exit(f\"{rel} has uncommitted edits. A pre-registration must be run exactly as committed.\")\n    t = json.loads(p.read_text(encoding=\"utf-8\"))\n    if any(\"<\" in s for nb in t[\"neighbours\"] for s in nb[\"fire\"] + nb[\"quiet\"] + [nb[\"label\"]]):\n        sys.exit(\"the tests file still has <placeholders>\")\n    prereg = subprocess.run([\"git\", \"log\", \"--diff-filter=A\", \"--format=%h\", \"--\", rel], cwd=ROOT, capture_output=True, text=True).stdout.split()[-1]\n    m = NEURON.match(t[\"neuron\"])\n    torch.cuda.set_per_process_memory_fraction(0.8)\n    model, tok, rec = load(m[\"model\"])\n    tok.padding_side = \"right\"\n    scan = explore.scan(m[\"model\"])\n    tests = []\n    for nb in t[\"neighbours\"]:\n        L, n = map(int, nb[\"unit\"][1:].split(\"/N\"))\n        pole = 0 if nb[\"pole\"] == \"+\" else 1\n        pmax, omax = float(scan[\"top_val\"][L, pole, 0, n]), float(scan[\"top_val\"][L, 1 - pole, 0, n])\n        ev = textinv.TextEvaluator(model, tok, rec, L, n, pmax, omax, 1.0 if pole == 0 else -1.0)\n        fire, quiet = ev(nb[\"fire\"]), ev(nb[\"quiet\"])\n        per = [{\"set\": s, \"i\": i, \"act\": round(r[\"act\"], 3), \"peak\": r[\"peak_token\"]} for s, rs in ((\"fire\", fire), (\"quiet\", quiet)) for i, r in enumerate(rs)]\n        nf, fp = sum(r[\"act\"] >= 0.3 for r in fire), sum(r[\"act\"] >= 0.3 for r in quiet)\n        tests.append({\"protocol\": t[\"protocol\"], \"tests_file\": rel, \"prereg_commit\": prereg, \"author\": a.author or t[\"contributor\"],\n                      \"n_fire\": nf, \"n_false_pos\": fp, \"n_written\": [len(fire), len(quiet)], \"per_sentence\": per})\n        print(f\"{nb['unit']}{nb['pole']}: fire {nf}/{len(fire)}, near misses firing {fp}/{len(quiet)} -> {'HELD' if nf >= 5 and fp <= 1 else 'FAILED'}\")\n    c = {\"id\": t[\"contribution\"], \"kind\": t[\"kind\"], \"neuron\": t[\"neuron\"], \"contributor\": t[\"contributor\"],\n         \"created\": dt.datetime.now(dt.timezone.utc).isoformat(timespec=\"seconds\"),\n         \"recipe\": {\"toolchain_commit\": _commit(), \"command\": f\"python -m bonsai_interp.graph.play run {rel}\"},\n         \"label\": t[\"neighbours\"][0][\"label\"], \"tests\": tests}\n    if t[\"kind\"] == \"qc\":\n        c[\"qc\"] = {\"verdict\": t[\"qc\"][\"verdict\"], \"label_under_test\": t[\"qc\"].get(\"label_under_test\")}\n        if t[\"qc\"][\"verdict\"] != \"refine\":\n            c.pop(\"label\")\n    for k in (\"short\", \"unit_kind\", \"confidence\", \"notes\", \"roles\", \"via\"):\n        if t.get(k) is not None:\n            c[k] = t[k]\n    out = p.with_name(p.name.replace(\".tests.json\", \".json\"))\n    out.write_text(json.dumps(c, ensure_ascii=False, indent=1) + \"\\n\", encoding=\"utf-8\", newline=\"\\n\")\n    print(f\"wrote {out.relative_to(ROOT)}. Next: python -m bonsai_interp.graph.fold, then commit the results in a second commit and open a PR.\")\n\n\ndef step(a):\n    import numpy as np","numLines":110,"startLine":1,"totalLines":325}},"tool_result_meta":[{"id":"toolu_01MQT4riDZG5y89JPRGFBQUv","permission_decision":{"decision":"accept","source":"config","reason_type":"rule"}}]}
