[--out card.json|card.md]\r\n\r\nA card holds, for both poles: the top corpus examples with the peak token in ⟦ ⟧, the pole's corpus max,\r\nits activation density (share of all scanned tokens above 0.1 and 0.3 of that max, read from the scan's\r\nlog-binned histograms), and the sign-regime split. It adds the direct logit effect of the neuron's output\r\ndirection (final norm gain, then the unembedding; weights only, read on the CPU) and flags for units an\r\n8 + 8 test can't pass (dense, positional). No GPU and no model load: a card takes a few seconds.\r\n\"\"\"\r\nimport json\r\nfrom functools import lru_cache\r\n\r\nimport numpy as np\r\n\r\nfrom bonsai_interp import explore\r\nfrom bonsai_interp.graph.contrib import NEURON, ROOT\r\n\r\n# flags (calibrated on the poles contributors marked dense / positional, against held token poles)\r\nDENSE_10 = 0.10     # >= 10% of tokens above 0.1 of max: an 8 + 8 test can hardly pass\r\nBROAD_10 = 0.01     # >= 1%: near misses will often fire weakly\r\nPOSITIONAL = 0.5    # >= half of the top 32 peaks within the first 16 tokens of a window, or one position\r\n\r\n\r\ndef parse(neuron):\r\n    \"\"\"'bonsai1/L9/N3688+' or 'L9/N3688' or '9/3688' -> (model, L, n, pole or None).\"\"\"\r\n    m = NEURON.match(neuron)\r\n    if m:\r\n        return m[\"model\"], int(m[\"L\"]), int(m[\"n\"]), m[\"pole\"]\r\n    s = neuron.removeprefix(\"bonsai1/\").replace(\"L\", \"\").replace(\"N\", \"\")\r\n    pole = s[-1] if s[-1] in \"+-\" else None\r\n    L, n = map(int, s.rstrip(\"+-\").split(\"/\"))\r\n    return \"bonsai1\", L, n, pole\r\n\r\n\r\ndef _above(h, lower, upper, t):\r\n    \"\"\"Count in a log-binned histogram above threshold t, splitting the straddling bin log-uniformly.\"\"\"\r\n    b = int(np.searchsorted(lower, t, side=\"right\")) - 1  # lower[b] <= t < lower[b+1]\r\n    n = h[b + 1:].sum()\r\n    lo, hi = lower[b], upper[b]\r\n    if lo > 0 and np.isfinite(hi) and hi > t:\r\n        n += h[b] * (np.log(hi) - np.log(t)) / (np.log(hi) - np.log(lo))\r\n    elif lo == 0 and hi > t:\r\n        n += h[b] * (hi - t) / hi\r\n    return float(n)\r\n\r\n\r\ndef pole_stats(name, L, n, pole):\r\n    s = explore.scan(name)\r\n    pi, regs = (0, [0, 1]) if pole == \"+\" else (1, [2, 3])\r\n    mx = float(s[\"top_val\"][L, pi, 0, n])\r\n    h = s[\"hist\"][L, n]  # (4 regimes, NB); bin b holds |a| in (bins[b-1], bins[b]]\r\n    bins = s[\"bins\"].astype(np.float64)\r\n    lower, upper = np.concatenate([[0], bins]), np.concatenate([bins, [np.inf]])\r\n    total = float(h.sum())\r\n    pole_h = h[regs].sum(0)\r\n    dens = {f: _above(pole_h, lower, upper, f * mx) / total for f in (0.1, 0.3)}\r\n    split = {}\r\n    for r in regs:  # regime shares among this pole's activations above 0.1 of max\r\n        split[explore.REGIMES[r]] = _above(h[r], lower, upper, 0.1 * mx)\r\n    tot = sum(split.values())\r\n    split = {k: round(v / tot, 3) if tot else None for k, v in split.items()}\r\n    pos = s[\"top_pos\"][L, pi, :, n]\r\n    pos = pos[np.isfinite(s[\"top_val\"][L, pi, :, n])]\r\n    vals, counts = np.unique(pos, return_counts=True)\r\n    early, mode_share = float((pos < 16).mean()) if len(pos) else 0.0, float(counts.max() / len(pos)) if len(pos) else 0.0\r\n    return {\"max\": round(mx, 3), \"density\": {\"0.1\": round(dens[0.1], 5), \"0.3\": round(dens[0.3], 5)},\r\n            \"regimes\": split, \"peak_positions\": {\"first16\": round(early, 3), \"commonest\": int(vals[counts.argmax()]) if len(pos) else None,\r\n                                                  \"commonest_share\": round(mode_share, 3)}}\r\n\r\n\r\ndef flags(st):\r\n    out = []\r\n    d = st[\"density\"][\"0.1\"]\r\n    if d >= DENSE_10:\r\n        out.append(f\"dense: {d:.1%} of tokens reach 0.1 of max; an 8 + 8 test can hardly pass (consider unit_kind 'dense / positional')\")\r\n    elif d >= BROAD_10:\r\n        out.append(f\"broad: {d:.1%} of tokens reach 0.1 of max; near misses will often fire weakly\")\r\n    pp = st[\"peak_positions\"]\r\n    if pp[\"first16\"] >= POSITIONAL or pp[\"commonest_share\"] >= POSITIONAL:\r\n        out.append(f\"positional: top peaks cluster at window position {pp['commonest']} \"\r\n                   f\"({pp['commonest_share']:.0%}; {pp['first16']:.0%} within the first 16 tokens)\")\r\n    if st[\"regimes\"]:\r\n        echo = max(st[\"regimes\"], key=lambda k: st[\"regimes\"][k] or 0)\r\n        if echo in (\"-x- echo\", \"-g +u leak\") and (st[\"regimes\"][echo] or 0) >= 0.6:\r\n            out.append(f\"gate-closed regime dominates ({echo} {st['regimes'][echo]:.0%})\")\r\n    return out\r\n\r\n\r\n@lru_cache(None)\r\ndef _weights(name):\r\n    \"\"\"(down_proj column reader, final norm gain in fp32, unembedding in fp16) on the CPU, from the\r\n    unpacked safetensors or from the 1-bit GGUF (bonsai_interp.gguf_weights), whichever the folder holds.\"\"\"\r\n    from bonsai_interp.model import MODELS\r\n    path = MODELS[name]\r\n    if not (path / \"model.safetensors.index.json\").exists():\r\n        from bonsai_interp import gguf_weights\r\n        ts = gguf_weights.by_name(path)\r\n        col = lambda L, n: gguf_weights.column(ts[f\"model.layers.{L}.mlp.down_proj.weight\"], n)\r\n        return col, gguf_weights.dense(ts[\"model.norm.weight\"]), gguf_weights.dense(ts[\"lm_head.weight\"]).half()\r\n    from safetensors import safe_open\r\n    idx = json.loads((path / \"model.safetensors.index.json\").read_text())[\"weight_map\"]\r\n    def get(t):\r\n        with safe_open(str(path / idx[t]), \"pt\", device=\"cpu\") as h:\r\n            return h.get_tensor(t)\r\n    def col(L, n):\r\n        t = f\"model.layers.{L}.mlp.down_proj.weight\"\r\n        with safe_open(str(path / idx[t]), \"pt\", device=\"cpu\") as h:\r\n            return h.get_slice(t)[:, n:n + 1][:, 0].float()\r\n    return col, get(\"model.norm.weight\").float(), get(\"lm_head.weight\")\r\n\r\n\r\ndef direct_logits(name, L, n, k=12):\r\n    \"\"\"Tokens the + pole's output direction promotes / suppresses directly (the - pole does the reverse):\r\n    W_U (g * d), d = down_proj column n, g = final RMSNorm gain. Same as probe/induce.py `direct`.\"\"\"\r\n    col, g, wu = _weights(name)\r\n    d = col(L, n)\r\n    logits = _matvec(wu, g * d)\r\n    tok = explore.tokenizer()\r\n    top, bot = logits.topk(k), (-logits).topk(k)\r\n    return {\"promotes\": [[tok.decode([i]), round(v, 3)] for i, v in zip(top.indices.tolist(), top.values.tolist())],\r\n            \"suppresses\": [[tok.decode([i]), round(-v, 3)] for i, v in zip(bot.indices.tolist(), bot.values.tolist())],\r\n            \"note\": \"for the + pole, per unit activation, before the final RMS normalisation; the - pole swaps the lists\"}\r\n\r\n\r\ndef _matvec(w, v, chunk=16384):\r\n    \"\"\"fp16 matrix x fp32 vector in chunks (keeps memory at a few hundred MB).\"\"\"\r\n    import torch\r\n    return torch.cat([w[i:i + chunk].float() @ v for i in range(0, w.shape[0], chunk)])\r\n\r\n\r\ndef card(neuron, k=6, logits=True, before=40, after=8):\r\n    name, L, n, pole = parse(neuron)\r\n    out = {\"neuron\": f\"{name}/L{L}/N{n}\", \"focus\": pole, \"poles\": {}}\r\n    for p in (\"+\", \"-\"):\r\n        st = pole_stats(name, L, n, p)\r\n        ex = explore.examples(name, L, n, 0 if p == \"+\" else 1, k, before=before, after=after)\r\n        st[\"examples\"] = [{\"act\": round(v, 3), \"frac\": round(v / st[\"max\"] * (1 if p == \"+\" else -1), 3) if st[\"max\"] else None,\r\n                           \"regime\": r, \"text\": t} for v, r, w, pos, t in ex]\r\n        st[\"flags\"] = flags(st)\r\n        out[\"poles\"][p] = st\r\n    if logits:\r\n        try:\r\n            out[\"direct\"] = direct_logits(name, L, n)\r\n        except (FileNotFoundError, KeyError, OSError) as e:\r\n            out[\"direct\"] = {\"error\": f\"weights unavailable: {e.__class__.__name__}\"}\r\n    rec = record(name, L, n)\r\n    out[\"records\"] = {p: {\"status\": r[\"status\"], \"label\": r.get(\"label\"), \"short\": r.get(\"short\")} for p, r in rec.items()}\r\n    return out\r\n\r\n\r\ndef record(name, L, n):\r\n    \"\"\"Derived graph records for the two poles, if any ({pole: record}).\"\"\"\r\n    out = {}\r\n    for p, suf in ((\"+\", \"pos\"), (\"-\", \"neg\")):\r\n        f = ROOT / \"graph\" / \"neurons\" / name / f\"L{L}_N{n}_{suf}.json\"\r\n        if f.exists():\r\n            out[p] = json.loads(f.read_text(encoding=\"utf-8\"))\r\n    return out\r\n\r\n\r\ndef render(c):\r\n    lines = [f\"=== {c['neuron']}  (card: scan + weights; not a tested label)\"]\r\n    for p in sorted(c[\"poles\"], key=lambda p: p != (c[\"focus\"] or \"+\")):\r\n        st = c[\"poles\"][p]\r\n        rec = c[\"records\"].get(p)\r\n        lines.append(f\"--- {p} pole   max {st['max']:.2f}   density >0.1·max {st['density']['0.1']:.3%}  >0.3·max {st['density']['0.3']:.3%}\"\r\n                     f\"   regimes {', '.join(f'{k} {v:.0%}' for k, v in st['regimes'].items() if v is not None)}\")\r\n        lines.append(f\"    record: {rec['status']}: {rec['label']}\" if rec else \"    record: none (unsurveyed)\")\r\n        for f in st[\"flags\"]:\r\n            lines.append(f\"    FLAG {f}\")\r\n        for e in st[\"examples\"]:\r\n            lines.append(f\"    {e['act']:8.2f} {e['regime']:>10} | {e['text'][-110:]}\")\r\n    d = c.get(\"direct\")\r\n    if d and \"error\" not in d:\r\n        lines.append(\"--- direct logit effect of the output direction (+ pole; the - pole reverses it)\")\r\n        lines.append(\"    promotes:   \" + \"  \".join(repr(t) for t, _ in d[\"promotes\"]))\r\n        lines.append(\"    suppresses: \" + \"  \".join(repr(t) for t, _ in d[\"suppresses\"]))\r\n    elif d:\r\n        lines.append(f\"--- direct logit effect: {d['error']}\")\r\n    return \"\\n\".join(lines)\r\n\r\n\r\ndef main(a):\r\n    c = card(a.neuron, k=a.k, logits=not a.no_logits)\r\n    print(render(c))\r\n    if a.out:\r\n        from pathlib import Path\r\n        p = Path(a.out)\r\n        p.write_text(json.dumps(c, ensure_ascii=False, indent=1) + \"\\n\" if p.suffix == \".json\" else render(c) + \"\\n\",\r\n                     encoding=\"utf-8\", newline=\"\\n\")\r\n        print(f\"wrote {p}\")\r\n\r\n\r\ndef compact(c, k=4, pre=70, post=24, tokens=8):\r\n    \"\"\"A small form of a card for the survey site: about 1.5 KB per neuron.\r\n    {\"+\"/\"-\": {\"m\": max, \"d\": [density 0.1, 0.3], \"r\": [gate-open share, gate-closed share], \"f\": [flag words],\r\n               \"x\": [[act, before, peak token, after], ...]}, \"u\": [[promoted by +], [suppressed by +]]}\"\"\"\r\n    out = {}\r\n    for p, st in c[\"poles\"].items():\r\n        xs = []\r\n        for e in st[\"examples\"][:k]:\r\n            a, rest = e[\"text\"].split(\"⟦\", 1)\r\n            b, after = rest.split(\"⟧\", 1)\r\n            xs.append([round(e[\"act\"], 2), a[-pre:], b, after[:post]])\r\n        out[p] = {\"m\": round(st[\"max\"], 2), \"d\": [st[\"density\"][\"0.1\"], st[\"density\"][\"0.3\"]],\r\n                  \"r\": [v if v is not None else 0 for v in st[\"regimes\"].values()],\r\n                  \"f\": [f.split(\":\")[0].split(\" \")[0] for f in st[\"flags\"]], \"x\": xs}\r\n    d = c.get(\"direct\") or {}\r\n    if \"promotes\" in d:\r\n        out[\"u\"] = [[t for t, _ in d[\"promotes\"][:tokens]], [t for t, _ in d[\"suppresses\"][:tokens]]]\r\n    return out\r\n\"\"\"Validate the graph (no model or torch needed).\r\n\r\n  python -m bonsai_interp.graph.validate             contributions only (what a PR is checked against)\r\n  python -m bonsai_interp.graph.validate --strict    also: derived files on disk match the fold exactly (main)\r\n\r\nChecks every contribution and pre-registration file against the rules in graph/SCHEMA.md and\r\nDATA_POLICY.md, then checks that the committed neuron records, edges and index are exactly what\r\n`fold` produces from the contributions (so no record was edited by hand).\r\n\"\"\"\r\nimport json\r\nimport sys\r\n\r\nfrom bonsai_interp.graph import contrib, fold\r\n\r\nROOT = contrib.ROOT\r\n\r\n\r\ndef main():\r\n    errs = []\r\n    results = contrib.load_all()\r\n    ids = {}\r\n    for path, c in results:\r\n        errs += contrib.check(path, c)\r\n        if c.get(\"id\") in ids:\r\n            errs.append(f\"duplicate contribution id {c['id']} ({ids[c['id']]} and {path.relative_to(ROOT).as_posix()})\")\r\n        ids[c.get(\"id\")] = path.relative_to(ROOT).as_posix()\r\n    tests = sorted(contrib.C.glob(\"*/*/*.tests.json\"))\r\n    for p in tests:\r\n        errs += contrib.check_tests_file(p)\r\n    stray = [p for p in contrib.C.rglob(\"*\") if p.is_file() and p.suffix not in (\".json\", \".md\")]\r\n    errs += [f\"{p.relative_to(ROOT).as_posix()}: only .json and .md files are allowed under graph/contributions\" for p in stray]\r\n    files = fold.fold()\r\n    if \"--strict\" in sys.argv:  # on main, after the merge agent's fold commit: derived files must match exactly\r\n        for p, s in files.items():\r\n            if not (ROOT / p).exists() or (ROOT / p).read_text(encoding=\"utf-8\") != s:\r\n                errs.append(f\"{p}: out of date with the contributions (run python -m bonsai_interp.graph.fold and commit)\")\r\n        for p in (ROOT / \"graph\" / \"neurons\").glob(\"*/*.json\"):\r\n            if p.relative_to(ROOT).as_posix() not in files:\r\n                errs.append(f\"{p.relative_to(ROOT).as_posix()}: record with no contributions (records are derived; do not add them by hand)\")\r\n    neurons = set(json.loads(files[\"graph/index.json\"])[\"neurons\"])\r\n    for e in json.loads(files[\"graph/edges.json\"])[\"edges\"]:\r\n        for end in (\"from\", \"to\"):\r\n            if e[end] not in neurons:\r\n                errs.append(f\"edge {e['from']} -> {e['to']} ({e['contribution']}): {e[end]} has no contributions of its own\")\r\n    for m in errs:\r\n        print(\"ERROR\", m)\r\n    print(f\"{len(results)} contributions, {len(tests)} pre-registration files, {len(neurons)} neuron poles; {len(errs)} problems\")\r\n    sys.exit(1 if errs else 0)\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","exit_code":0,"status":"completed"}}
runs\playtest\2026-10-18\sweep-2-codex.jsonl:25:{"type":"item.completed","item":{"id":"item_12","type":"command_execution","command":"\"C:\\\\windows\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe\" -Command 'Get-Content -Encoding utf8 bonsai_interp/explore.py | Select-Object -First 140; Get-Content -Encoding utf8 bonsai_interp/graph/contrib.py | Select-Object -First 250; Get-Content -Encoding utf8 .github/workflows/graph-check.yml'","aggregated_output":"\"\"\"Forward view of a neuron from a corpus scan: top examples per pole, regime stats.\r\n\r\nUsage: python -m bonsai_interp.explore --model bonsai1 --neuron 18/4242 [--pole +] [--k 12]\r\n\"\"\"\r\nimport argparse\r\nfrom functools import lru_cache\r\n\r\nimport numpy as np\r\nfrom transformers import AutoTokenizer\r\n\r\nfrom bonsai_interp.model import MODELS, ROOT\r\n\r\nREGIMES = [\"+x+\", \"-x- echo\", \"+g -u\", \"-g +u leak\"]\r\n\r\n\r\n@lru_cache(None)\r\ndef scan(name):\r\n    return dict(np.load(ROOT / \"data\" / f\"scan_{name}.npz\"))\r\n\r\n\r\n@lru_cache(None)\r\ndef corpus():\r\n    return np.load(ROOT / \"data\" / \"corpus.npz\")[\"tokens\"]\r\n\r\n\r\n@lru_cache(None)\r\ndef tokenizer():\r\n    return AutoTokenizer.from_pretrained(MODELS[\"bonsai1\"])\r\n\r\n\r\ndef examples(name, L, n, pole=0, k=12, before=48, after=8):\r\n    \"\"\"[(activation, regime, window, pos, text with the peak token in ⟦ ⟧)]\"\"\"\r\n    s, tok, toks = scan(name), tokenizer(), corpus()\r\n    out = []\r\n    for j in range(k):\r\n        v = s[\"top_val\"][L, pole, j, n]\r\n        if not np.isfinite(v):\r\n            break\r\n        w, p, r = s[\"top_win\"][L, pole, j, n], int(s[\"top_pos\"][L, pole, j, n]), s[\"top_reg\"][L, pole, j, n]\r\n        ids = toks[w]\r\n        text = tok.decode(ids[max(0, p - before):p]) + \"⟦\" + tok.decode(ids[p:p + 1]) + \"⟧\" + \\\r\n            tok.decode(ids[p + 1:p + 1 + after])\r\n        out.append((float(v) * (1 if pole == 0 else -1), REGIMES[r], int(w), p, text.replace(\"\\n\", \"⏎\")))\r\n    return out\r\n\r\n\r\ndef regime_stats(name, L, n):\r\n    \"\"\"Share of each regime among activations above 10% / 30% of each pole's max.\"\"\"\r\n    s = scan(name)\r\n    h, bins = s[\"hist\"][L, n], s[\"bins\"]  # (4, NB): bin b holds |a| in [bins[b-1], bins[b])\r\n    lower = np.concatenate([[0], bins])\r\n    res = {}\r\n    for pole, regs in ((\"+\", [0, 1]), (\"-\", [2, 3])):\r\n        mx = abs(s[\"top_val\"][L, 0 if pole == \"+\" else 1, 0, n])\r\n        for frac in (0.1, 0.3):\r\n            mask = lower >= frac * mx\r\n            counts = h[regs][:, mask].sum(1)\r\n            tot = counts.sum()\r\n            res[f\"{pole}pole>{int(frac * 100)}%max\"] = {\r\n                \"count\": int(tot),\r\n                **{REGIMES[r]: round(float(c) / tot, 3) if tot else None for r, c in zip(regs, counts)}}\r\n        res[f\"{pole}max\"] = float(mx)\r\n    return res\r\n\r\n\r\ndef show(name, L, n, poles=(\"+\", \"-\"), k=12):\r\n    print(f\"=== {name} L{L}/N{n}\")\r\n    for key, v in regime_stats(name, L, n).items():\r\n        print(f\"  {key}: {v}\")\r\n    for pole in poles:\r\n        print(f\"--- {pole} pole\")\r\n        for v, r, w, p, text in examples(name, L, n, 0 if pole == \"+\" else 1, k):\r\n            print(f\"{v:9.2f} {r:>10} | {text}\")\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    ap = argparse.ArgumentParser()\r\n    ap.add_argument(\"--model\", default=\"bonsai1\")\r\n    ap.add_argument(\"--neuron\", required=True)\r\n    ap.add_argument(\"--pole\", default=\"+-\")\r\n    ap.add_argument(\"--k\", type=int, default=12)\r\n    a = ap.parse_args()\r\n    L, n = map(int, a.neuron.split(\"/\"))\r\n    show(a.model, L, n, tuple(a.pole), a.k)\r\n\"\"\"Contributions: immutable, append-only files that are the only way information enters the graph.\r\n\r\nLayout (one folder per neuron pole):\r\n\r\n  graph/contributions/<model>/L{L}_N{n}_{pos|neg}/<id>.tests.json   pre-registration (committed FIRST)\r\n  graph/contributions/<model>/L{L}_N{n}_{pos|neg}/<id>.json         results (committed in a LATER commit)\r\n\r\n`<id>` is `YYYY-MM-DD-<github handle>-<4+ chars>`, unique forever. Contributions are never edited\r\nor deleted; a correction is a new contribution. Neuron records under graph/neurons/ are derived\r\nfrom contributions by `fold` and are never edited by hand.\r\n\r\nKinds: interpret (label a pole), qc (re-test a label), replicate (blind clean-room run), map (edges only).\r\n\"\"\"\r\nimport json\r\nimport re\r\nfrom pathlib import Path\r\n\r\nfrom bonsai_interp.graph.protocols import LEGACY, PROTOCOLS\r\n\r\nROOT = Path(__file__).resolve().parents[2]\r\nC = ROOT / \"graph\" / \"contributions\"\r\nKINDS = {\"interpret\", \"qc\", \"replicate\", \"map\"}\r\nQC_VERDICTS = {\"confirm\", \"dispute\", \"refine\"}\r\nID = re.compile(r\"^\\d{4}-\\d{2}-\\d{2}-[A-Za-z0-9-]+-[A-Za-z0-9]{4,}$|^core-[a-z0-9-]+$\")\r\nNEURON = re.compile(r\"^(?P<model>[a-z0-9_]+)/L(?P<L>\\d+)/N(?P<n>\\d+)(?P<pole>[+-])$\")\r\nLOCAL_PATH = re.compile(r\"(?i)\\b[a-z]:[\\\\/]+users[\\\\/]|/home/[a-z]|/Users/[A-Za-z]\")\r\nMAX_FILE = 64 * 1024\r\nMETHODS_REQUIRED_FROM = \"2026-10-18T18:30\"  # contributions created earlier predate the methods block\r\nMAX_NOTES = 4000\r\nMAX_EXAMPLE = 400\r\n\r\n\r\ndef folder_for(neuron):\r\n    m = NEURON.match(neuron)\r\n    return C / m[\"model\"] / f\"L{m['L']}_N{m['n']}_{'pos' if m['pole'] == '+' else 'neg'}\"\r\n\r\n\r\ndef load_all():\r\n    \"\"\"[(path, contribution)] for every results file, in deterministic order.\"\"\"\r\n    out = []\r\n    for p in sorted(C.glob(\"*/*/*.json\")):\r\n        if p.name.endswith(\".tests.json\"):\r\n            continue\r\n        out.append((p, json.loads(p.read_text(encoding=\"utf-8\"))))\r\n    return out\r\n\r\n\r\ndef check(path: Path, c: dict):\r\n    \"\"\"Problems with one results file (empty list = fine).\"\"\"\r\n    errs = []\r\n    say = errs.append\r\n    rel = path.relative_to(ROOT).as_posix()\r\n    if path.stat().st_size > MAX_FILE:\r\n        say(f\"{rel}: larger than {MAX_FILE // 1024} KB; move bulky material to the library and list it under 'artifacts'\")\r\n    if LOCAL_PATH.search(path.read_text(encoding=\"utf-8\")):\r\n        say(f\"{rel}: contains a local filesystem path\")\r\n    for k in (\"id\", \"kind\", \"neuron\", \"created\", \"contributor\"):\r\n        if not c.get(k):\r\n            say(f\"{rel}: needs '{k}'\")\r\n    if errs:\r\n        return errs\r\n    if not ID.match(c[\"id\"]) or path.stem != c[\"id\"]:\r\n        say(f\"{rel}: id must match the file name and look like YYYY-MM-DD-<handle>-<suffix>\")\r\n    if c[\"kind\"] not in KINDS:\r\n        say(f\"{rel}: kind must be one of {sorted(KINDS)}\")\r\n    if not NEURON.match(c[\"neuron\"]) or folder_for(c[\"neuron\"]) != path.parent:\r\n        say(f\"{rel}: neuron {c['neuron']!r} does not match its folder\")\r\n    if not c[\"id\"].startswith(\"core-\") and c[\"kind\"] in (\"interpret\", \"qc\", \"replicate\") and c[\"created\"] >= METHODS_REQUIRED_FROM:\r\n        mt = c.get(\"methods\") or {}\r\n        if not mt.get(\"agent\") or not isinstance(mt.get(\"screens\"), list) or not mt.get(\"screens\"):\r\n            say(f\"{rel}: needs a 'methods' block with 'agent' and a non-empty 'screens' list (see bonsai_interp/graph/methods.py)\")\r\n    if c[\"kind\"] in (\"interpret\", \"qc\") and not c.get(\"tests\"):\r\n        say(f\"{rel}: an {c['kind']} contribution needs at least one pre-registered test\")\r\n    if c[\"kind\"] == \"interpret\" and not c.get(\"label\"):\r\n        say(f\"{rel}: an interpret contribution needs a 'label'\")\r\n    if c[\"kind\"] == \"qc\":\r\n        q = c.get(\"qc\") or {}\r\n        if q.get(\"verdict\") not in QC_VERDICTS:\r\n            say(f\"{rel}: qc.verdict must be one of {sorted(QC_VERDICTS)}\")\r\n        if q.get(\"verdict\") == \"refine\" and not c.get(\"label\"):\r\n            say(f\"{rel}: a 'refine' QC must propose a new 'label'\")\r\n    for i, t in enumerate(c.get(\"tests\", [])):\r\n        proto = LEGACY.get(t.get(\"protocol\"), t.get(\"protocol\"))\r\n        if proto not in PROTOCOLS:\r\n            say(f\"{rel}: tests[{i}] protocol {t.get('protocol')!r} unknown (known: {sorted(PROTOCOLS)})\")\r\n        tf = t.get(\"tests_file\")\r\n        if not tf:\r\n            say(f\"{rel}: tests[{i}] needs 'tests_file' (the pre-registration)\")\r\n        elif not (ROOT / tf).exists():\r\n            say(f\"{rel}: tests[{i}].tests_file does not exist: {tf}\")\r\n    if len(c.get(\"notes\", \"\")) > MAX_NOTES:\r\n        say(f\"{rel}: notes longer than {MAX_NOTES} characters; put long write-ups in the library\")\r\n    for e in c.get(\"examples\", []):\r\n        if len(e) > MAX_EXAMPLE:\r\n            say(f\"{rel}: corpus examples are capped at {MAX_EXAMPLE} characters each\")\r\n            break\r\n    for a in c.get(\"artifacts\", []):\r\n        if not (a.get(\"sha256\") and a.get(\"url\") and a.get(\"name\")):\r\n            say(f\"{rel}: each artifact needs name, url and sha256\")\r\n    for e in c.get(\"edges\", []):\r\n        if not (NEURON.match(e.get(\"from\", \"\")) and NEURON.match(e.get(\"to\", \"\")) and e.get(\"kind\") and \"weight\" in e):\r\n            say(f\"{rel}: each edge needs from, to (neuron ids), kind and weight\")\r\n    return errs\r\n\r\n\r\ndef check_tests_file(path: Path):\r\n    errs, rel = [], path.relative_to(ROOT).as_posix()\r\n    if path.stat().st_size > MAX_FILE:\r\n        errs.append(f\"{rel}: larger than {MAX_FILE // 1024} KB\")\r\n    try:\r\n        t = json.loads(path.read_text(encoding=\"utf-8\"))\r\n    except json.JSONDecodeError as e:\r\n        return [f\"{rel}: invalid JSON ({e})\"]\r\n    if LOCAL_PATH.search(path.read_text(encoding=\"utf-8\")):\r\n        errs.append(f\"{rel}: contains a local filesystem path\")\r\n    if not (t.get(\"neighbours\") or t.get(\"sentences\") or t.get(\"tests\")):\r\n        errs.append(f\"{rel}: a tests file needs 'neighbours' (quick tests), 'sentences' (held-out) or 'tests'\")\r\n    return errs\r\nGet-Content : Cannot find path \r\n'~\\Documents\\survey-playtest\\bonsai-interp\\.github\\workflows\\graph-check.yml' because it does not exist.\r\nAt line:2 char:167\r\n+ ... -First 250; Get-Content -Encoding utf8 .github/workflows/graph-check. ...\r\n+                 ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\r\n    + CategoryInfo          : ObjectNotFound: (~\\...graph-check.yml:String) [Get-Content], ItemNotFoundEx \r\n   ception\r\n    + FullyQualifiedErrorId : PathNotFound,Microsoft.PowerShell.Commands.GetContentCommand\r\n \r\n","exit_code":1,"status":"failed"}}
runs\playtest\2026-10-18\sweep-2-codex.jsonl:30:{"type":"item.completed","item":{"id":"item_15","type":"command_execution","command":"\"C:\\\\windows\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe\" -Command 'Get-Content -Encoding utf8 .github/workflows/checks.yml; Get-Content -Encoding utf8 bonsai_interp/probe/bands.py | Select-Object -First 110'","aggregated_output":"name: checks\r\n# Every PR: contributions are valid, append-only, pre-registered before their results, within the size caps,\r\n# and carry no derived graph files. On main: the derived files match a fresh fold (validate --strict).\r\n# Standard library only, so this takes seconds.\r\non:\r\n  pull_request:\r\n  push:\r\n    branches: [main]\r\npermissions:\r\n  contents: read\r\njobs:\r\n  graph:\r\n    runs-on: ubuntu-latest\r\n    steps:\r\n      - uses: actions/checkout@v4\r\n        with:\r\n          fetch-depth: 0\r\n      - uses: actions/setup-python@v5\r\n        with:\r\n          python-version: \"3.12\"\r\n      - name: Validate contributions\r\n        if: github.event_name == 'pull_request'\r\n        run: python -m bonsai_interp.graph.validate\r\n      - name: Check pre-registration order, append-only, size caps, no derived files\r\n        if: github.event_name == 'pull_request'\r\n        run: python -m bonsai_interp.graph.check_prereg --base origin/${{ github.base_ref }}\r\n      - name: Derived files match the contributions (circuit breaker)\r\n        if: github.event_name == 'push'\r\n        run: python -m bonsai_interp.graph.validate --strict\r\n\"\"\"Full-distribution view of a few neurons: every token's activation over a corpus slice, so the\r\nweak and middle activations (not only the top 32) can be sampled, annotated and tested.\r\n\r\n  scan     record the given neurons on every token of N windows -> data/bands_<tag>.npz\r\n  sample   for a neuron and pole, draw contexts from activation bands (fractions of corpus max)\r\n\r\n  python -m bonsai_interp.probe.bands scan --units 9/3688,10/6901,... --windows 1000 --tag mine   (about 3-4 min per 1,000 windows)\r\n  python -m bonsai_interp.probe.bands sample --units 9/3688 --tag mine --pole + --k 8\r\n\"\"\"\r\nimport argparse\r\nimport re\r\nimport sys\r\nimport time\r\n\r\nimport numpy as np\r\nimport torch\r\n\r\nfrom bonsai_interp import explore\r\nfrom bonsai_interp.env import DEVICE\r\nfrom bonsai_interp.model import ROOT, StopForward, load\r\n\r\nBANDS = [(0.05, 0.1), (0.1, 0.2), (0.2, 0.3), (0.3, 0.5), (0.5, 10.0)]\r\n\r\n\r\n@torch.no_grad()\r\ndef scan(units, windows, tag, batch=8):\r\n    toks = explore.corpus()[:windows]\r\n    model, tok, rec = load(\"bonsai1\")\r\n    layers = sorted({L for L, _ in units})\r\n    out = {u: np.zeros((len(toks), toks.shape[1]), np.float16) for u in units}\r\n    rec.mode, rec.layers, rec.stop_at = \"act\", set(layers), layers[-1]\r\n    t0 = time.time()\r\n    for s in range(0, len(toks), batch):\r\n        x = torch.from_numpy(toks[s:s + batch].astype(np.int64)).to(DEVICE)\r\n        try:\r\n            model.model(x)\r\n        except StopForward:\r\n            pass\r\n        for L, n in units:\r\n            out[(L, n)][s:s + batch] = rec.store[L][:, :, n].float().cpu().numpy().astype(np.float16)\r\n        rec.clear()\r\n        if (s // batch) % 100 == 0:\r\n            done = s + batch\r\n            eta = (time.time() - t0) / done * (len(toks) - done)\r\n            print(f\"{done}/{len(toks)} windows, about {eta / 60:.1f} min left\", flush=True)\r\n    rec.mode, rec.stop_at = None, None\r\n    np.savez(ROOT / \"data\" / f\"bands_{tag}.npz\", windows=windows,\r\n             **{f\"L{L}_N{n}\": a for (L, n), a in out.items()})\r\n    print(\"saved\", ROOT / \"data\" / f\"bands_{tag}.npz\")\r\n\r\n\r\ndef load_bands(tag):\r\n    return np.load(ROOT / \"data\" / f\"bands_{tag}.npz\")\r\n\r\n\r\ndef sample(tag, L, n, pole, k=30, seed=0, before=60, after=12, bands=BANDS):\r\n    \"\"\"{band: {\"count\": tokens in band, \"examples\": [(frac, text with ⟦peak⟧)]}} for one pole.\r\n    At most one example per window, so a single document cannot dominate a band.\"\"\"\r\n    d = load_bands(tag)\r\n    a = d[f\"L{L}_N{n}\"].astype(np.float32) * (1 if pole == \"+\" else -1)\r\n    pmax = float(explore.scan(\"bonsai1\")[\"top_val\"][L, 0 if pole == \"+\" else 1, 0, n])\r\n    f = a / pmax\r\n    toks, tk = explore.corpus(), explore.tokenizer()\r\n    rng = np.random.default_rng(seed)\r\n    res = {}\r\n    for lo, hi in bands:\r\n        w, p = np.where((f >= lo) & (f < hi))\r\n        key = f\"{lo:.2f}-{hi:.2f}\" if hi < 10 else f\"≥{lo:.2f}\"\r\n        ex = []\r\n        if len(w):\r\n            order = rng.permutation(len(w))\r\n            seen = set()\r\n            for i in order:\r\n                if w[i] in seen:\r\n                    continue\r\n                seen.add(w[i])\r\n                ids = toks[w[i]]\r\n                q = int(p[i])\r\n                text = tk.decode(ids[max(0, q - before):q]) + \"⟦\" + tk.decode(ids[q:q + 1]) + \"⟧\" + tk.decode(ids[q + 1:q + 1 + after])\r\n                ex.append({\"frac\": round(float(f[w[i], q]), 3), \"text\": text.replace(\"\\n\", \"⏎\")})\r\n                if len(ex) >= k:\r\n                    break\r\n        res[key] = {\"count\": int(len(w)), \"examples\": ex}\r\n    res[\"_total_tokens\"] = int(a.size)\r\n    return res\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    ap = argparse.ArgumentParser()\r\n    ap.add_argument(\"stage\")\r\n    ap.add_argument(\"--units\", required=True)\r\n    ap.add_argument(\"--windows\", type=int, default=6000)\r\n    ap.add_argument(\"--tag\", default=\"web\")\r\n    ap.add_argument(\"--pole\", default=\"+\", help=\"sample: which pole\")\r\n    ap.add_argument(\"--k\", type=int, default=8, help=\"sample: contexts per band\")\r\n    a = ap.parse_args()\r\n    units = [tuple(map(int, u.split(\"/\"))) for u in a.units.split(\",\")]\r\n    if a.stage == \"scan\":\r\n        scan(units, a.windows, a.tag)\r\n    elif a.stage == \"sample\":\r\n        L, n = units[0]\r\n        res = sample(a.tag, L, n, a.pole, k=a.k)\r\n        for band, v in res.items():\r\n            if band.startswith(\"_\"):\r\n                continue\r\n            print(f\"== band {band}: {v['count']:,} tokens\")\r\n            for e in v[\"examples\"]:\r\n                print(f\"  {e['frac']:.2f} | {e['text'][-150:]}\")\r\n    else:\r\n        sys.exit(f\"unknown stage {a.stage!r}: use scan or sample\")\r\n","exit_code":0,"status":"completed"}}
