   n.add_argument(\"--verdict\", choices=[\"confirm\", \"dispute\", \"refine\"], default=\"confirm\",\r\n                   help=\"qc only: confirm = re-test the label as is; refine = propose a better label\")\r\n    r = sub.add_parser(\"run\", help=\"score one or more committed pre-registrations (one model load for all)\")\r\n    r.add_argument(\"tests_files\", nargs=\"*\")\r\n    r.add_argument(\"--list\", help=\"a file listing tests files, one per line (e.g. .sweep/latest.txt from play draw); works in any shell\")\r\n    r.add_argument(\"--author\", help=\"only when the SENTENCES came from someone else, e.g. 'bonsai' when the model wrote them or 'twitch-chat'; \"\r\n                   \"who did the work goes in the tests file's methods.agent, not here\")\r\n    fl = sub.add_parser(\"fill\", help=\"fill the drawn tests files from one JSON plan (LF endings; checks the keys)\")\r\n    fl.add_argument(\"--plan\", required=True, help='{\"<pole id>\": {\"label\": ..., \"fire\": [8], \"quiet\": [8], \"short\"/\"unit_kind\"/\"confidence\"/\"notes\": ...}}')\r\n    fl.add_argument(\"--list\", default=\".sweep/latest.txt\", help=\"the tests files (default: the last play draw)\")\r\n    fl.add_argument(\"--agent\", help=\"methods.agent for every file, e.g. 'claude-code opus-5.5'\")\r\n    dr = sub.add_parser(\"draw\", help=\"k random poles with no record yet (for a sweep)\")\r\n    dr.add_argument(\"--k\", type=int, default=16)\r\n    dr.add_argument(\"--seed\", type=int, help=\"reproducible draw (default: random)\")\r\n    dr.add_argument(\"--layers\", default=\"0-35\")\r\n    dr.add_argument(\"--handle\", help=\"also write an interpret tests file for each drawn pole (play new), as a sweep does\")\r\n    s = sub.add_parser(\"step\")\r\n    s.add_argument(\"--neuron\", required=True)\r\n    s.add_argument(\"--k\", type=int, default=4)\r\n    lk = sub.add_parser(\"look\")\r\n    lk.add_argument(\"--neuron\", required=True)\r\n    pr = sub.add_parser(\"probe\", help=\"exploration: score sentences on a pole, nothing recorded\")\r\n    pr.add_argument(\"--neuron\")\r\n    pr.add_argument(\"sentences\", nargs=\"*\")\r\n    pr.add_argument(\"--file\", help=\"one sentence per line\")\r\n    pr.add_argument(\"--plan\", help='JSON {\"<pole id>\": [\"sentence\", ...], ...}: probe many poles with one model load')\r\n    e = sub.add_parser(\"edge\", help=\"record a measured edge between two poles\")\r\n    e.add_argument(\"--from\", dest=\"src\", required=True)\r\n    e.add_argument(\"--to\", dest=\"dst\", required=True)\r\n    e.add_argument(\"--kind\", default=\"feeds\", choices=[\"feeds\", \"reads\", \"gates\", \"co-fires\"])\r\n    e.add_argument(\"--weight\", type=float, required=True, help=\"feeds: share of the target's activation lost when the source is zeroed\")\r\n    e.add_argument(\"--method\", default=\"single-unit zero ablation (play step)\")\r\n    e.add_argument(\"--handle\", required=True)\r\n    c = sub.add_parser(\"card\", help=\"a card for any neuron (labelled or not): examples, density, regimes, logit effect\")\r\n    c.add_argument(\"--neuron\", required=True, nargs=\"+\", help=\"bonsai1/L9/N3688+ (the pole is shown first) or L9/N3688; \"\r\n                   \"give several to print several cards in one go (much faster than one call each)\")\r\n    c.add_argument(\"--k\", type=int, default=6, help=\"top examples per pole\")\r\n    c.add_argument(\"--out\", help=\"also write the card: .json for data, anything else for the text\")\r\n    c.add_argument(\"--no-logits\", action=\"store_true\", help=\"skip the direct logit effect (no weights needed)\")\r\n    w = sub.add_parser(\"which\", help=\"reverse search: text -> poles firing on each token, or --token -> poles\")\r\n    w.add_argument(\"text\", nargs=\"?\")\r\n    w.add_argument(\"--token\", help=\"a token as the model sees it, e.g. ' nerve' (leading space matters)\")\r\n    w.add_argument(\"--k\", type=int, default=8, help=\"poles per token\")\r\n    w.add_argument(\"--min-max\", type=float, default=0.5, help=\"ignore poles whose corpus max is below this (fractions of a tiny max are noise)\")\r\n    w.add_argument(\"--keep-dense\", action=\"store_true\", help=\"also list dense / positional poles (hidden by default)\")\r\n    w.add_argument(\"--rebuild\", action=\"store_true\", help=\"--token: rebuild the token index from the scan\")\r\n    d = sub.add_parser(\"doctor\", help=\"check this machine is ready to play\")\r\n    d.add_argument(\"--quick\", action=\"store_true\", help=\"skip loading the model\")\r\n    b = sub.add_parser(\"brief\", help=\"print the full instructions for a mission (for an AI agent)\")\r\n    b.add_argument(\"kind\", choices=[\"interpret\", \"sweep\", \"qc\", \"step\", \"blind\"])\r\n    b.add_argument(\"--neuron\", help=\"the pole (every kind but sweep)\")\r\n    b.add_argument(\"--k\", type=int, default=16, help=\"sweep: how many poles\")\r\n    b.add_argument(\"--handle\", default=\"<your-github-handle>\")\r\n    b.add_argument(\"--gmoo\", action=\"store_true\", help=\"include the optional globalMOO step\")\r\n    b.add_argument(\"--depth\", choices=[\"quick\", \"standard\", \"deep\"], default=\"quick\",\r\n                   help=\"quick (~5-10 min, the default), standard (~30-45 min) or deep (hours)\")\r\n    a = ap.parse_args()\r\n    if a.cmd in (\"doctor\", \"brief\"):\r\n        from bonsai_interp.graph import agent\r\n        return getattr(agent, a.cmd)(a)\r\n    if a.cmd == \"card\":\r\n        from bonsai_interp.graph import card\r\n        return card.main(a)\r\n    if a.cmd == \"which\":\r\n        from bonsai_interp.graph import which\r\n        return which.main(a)\r\n    {\"new\": new, \"draw\": draw, \"fill\": fill, \"run\": run, \"step\": step, \"look\": look, \"edge\": edge, \"probe\": probe}[a.cmd](a)\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n\"\"\"Neuron cards: a compact, label-free view of any of the 442,368 neurons, from the corpus scan and the weights.\r\n\r\n  python -m bonsai_interp.graph.play card --neuron bonsai1/L9/N3688+ [--k 6] [--out card.json|card.md]\r\n\r\nA card holds, for both poles: the top corpus examples with the peak token in ⟦ ⟧, the pole's corpus max,\r\nits activation density (share of all scanned tokens above 0.1 and 0.3 of that max, read from the scan's\r\nlog-binned histograms), and the sign-regime split. It adds the direct logit effect of the neuron's output\r\ndirection (final norm gain, then the unembedding; weights only, read on the CPU) and flags for units an\r\n8 + 8 test can't pass (dense, positional). No GPU and no model load: a card takes a few seconds.\r\n\"\"\"\r\nimport json\r\nfrom functools import lru_cache\r\n\r\nimport numpy as np\r\n\r\nfrom bonsai_interp import explore\r\nfrom bonsai_interp.graph.contrib import NEURON, ROOT\r\n\r\n# flags (calibrated on the poles contributors marked dense / positional, against held token poles)\r\nDENSE_10 = 0.10     # >= 10% of tokens above 0.1 of max: an 8 + 8 test can hardly pass\r\nBROAD_10 = 0.01     # >= 1%: near misses will often fire weakly\r\nPOSITIONAL = 0.5    # >= half of the top 32 peaks within the first 16 tokens of a window, or one position\r\n\r\n\r\ndef parse(neuron):\r\n    \"\"\"'bonsai1/L9/N3688+' or 'L9/N3688' or '9/3688' -> (model, L, n, pole or None).\"\"\"\r\n    m = NEURON.match(neuron)\r\n    if m:\r\n        return m[\"model\"], int(m[\"L\"]), int(m[\"n\"]), m[\"pole\"]\r\n    s = neuron.removeprefix(\"bonsai1/\").replace(\"L\", \"\").replace(\"N\", \"\")\r\n    pole = s[-1] if s[-1] in \"+-\" else None\r\n    L, n = map(int, s.rstrip(\"+-\").split(\"/\"))\r\n    return \"bonsai1\", L, n, pole\r\n\r\n\r\ndef _above(h, lower, upper, t):\r\n    \"\"\"Count in a log-binned histogram above threshold t, splitting the straddling bin log-uniformly.\"\"\"\r\n    b = int(np.searchsorted(lower, t, side=\"right\")) - 1  # lower[b] <= t < lower[b+1]\r\n    n = h[b + 1:].sum()\r\n    lo, hi = lower[b], upper[b]\r\n    if lo > 0 and np.isfinite(hi) and hi > t:\r\n        n += h[b] * (np.log(hi) - np.log(t)) / (np.log(hi) - np.log(lo))\r\n    elif lo == 0 and hi > t:\r\n        n += h[b] * (hi - t) / hi\r\n    return float(n)\r\n\r\n\r\ndef pole_stats(name, L, n, pole):\r\n    s = explore.scan(name)\r\n    pi, regs = (0, [0, 1]) if pole == \"+\" else (1, [2, 3])\r\n    mx = float(s[\"top_val\"][L, pi, 0, n])\r\n    h = s[\"hist\"][L, n]  # (4 regimes, NB); bin b holds |a| in (bins[b-1], bins[b]]\r\n    bins = s[\"bins\"].astype(np.float64)\r\n    lower, upper = np.concatenate([[0], bins]), np.concatenate([bins, [np.inf]])\r\n    total = float(h.sum())\r\n    pole_h = h[regs].sum(0)\r\n    dens = {f: _above(pole_h, lower, upper, f * mx) / total for f in (0.1, 0.3)}\r\n    split = {}\r\n    for r in regs:  # regime shares among this pole's activations above 0.1 of max\r\n        split[explore.REGIMES[r]] = _above(h[r], lower, upper, 0.1 * mx)\r\n    tot = sum(split.values())\r\n    split = {k: round(v / tot, 3) if tot else None for k, v in split.items()}\r\n    pos = s[\"top_pos\"][L, pi, :, n]\r\n    pos = pos[np.isfinite(s[\"top_val\"][L, pi, :, n])]\r\n    vals, counts = np.unique(pos, return_counts=True)\r\n    early, mode_share = float((pos < 16).mean()) if len(pos) else 0.0, float(counts.max() / len(pos)) if len(pos) else 0.0\r\n    return {\"max\": round(mx, 3), \"density\": {\"0.1\": round(dens[0.1], 5), \"0.3\": round(dens[0.3], 5)},\r\n            \"regimes\": split, \"peak_positions\": {\"first16\": round(early, 3), \"commonest\": int(vals[counts.argmax()]) if len(pos) else None,\r\n                                                  \"commonest_share\": round(mode_share, 3)}}\r\n\r\n\r\ndef flags(st):\r\n    out = []\r\n    d = st[\"density\"][\"0.1\"]\r\n    if d >= DENSE_10:\r\n        out.append(f\"dense: {d:.1%} of tokens reach 0.1 of max; an 8 + 8 test can hardly pass (consider unit_kind 'dense / positional')\")\r\n    elif d >= BROAD_10:\r\n        out.append(f\"broad: {d:.1%} of tokens reach 0.1 of max; near misses will often fire weakly\")\r\n    pp = st[\"peak_positions\"]\r\n    if pp[\"first16\"] >= POSITIONAL or pp[\"commonest_share\"] >= POSITIONAL:\r\n        out.append(f\"positional: top peaks cluster at window position {pp['commonest']} \"\r\n                   f\"({pp['commonest_share']:.0%}; {pp['first16']:.0%} within the first 16 tokens)\")\r\n    if st[\"regimes\"]:\r\n        echo = max(st[\"regimes\"], key=lambda k: st[\"regimes\"][k] or 0)\r\n        if echo in (\"-x- echo\", \"-g +u leak\") and (st[\"regimes\"][echo] or 0) >= 0.6:\r\n            out.append(f\"gate-closed regime dominates ({echo} {st['regimes'][echo]:.0%})\")\r\n    return out\r\n\r\n\r\n@lru_cache(None)\r\ndef _weights(name):\r\n    \"\"\"(down_proj column reader, final norm gain in fp32, unembedding in fp16) on the CPU, from the\r\n    unpacked safetensors or from the 1-bit GGUF (bonsai_interp.gguf_weights), whichever the folder holds.\"\"\"\r\n    from bonsai_interp.model import MODELS\r\n    path = MODELS[name]\r\n    if not (path / \"model.safetensors.index.json\").exists():\r\n        from bonsai_interp import gguf_weights\r\n        ts = gguf_weights.by_name(path)\r\n        col = lambda L, n: gguf_weights.column(ts[f\"model.layers.{L}.mlp.down_proj.weight\"], n)\r\n        return col, gguf_weights.dense(ts[\"model.norm.weight\"]), gguf_weights.dense(ts[\"lm_head.weight\"]).half()\r\n","exit_code":0,"status":"completed"}}
runs\playtest\2026-10-18\sweep-10-codex.jsonl:51:{"type":"item.completed","item":{"id":"item_25","type":"command_execution","command":"\"C:\\\\windows\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe\" -Command \"git log -2 --format='%H %s'; Get-Content -Encoding utf8 graph/SCHEMA.md | Select-Object -First 190; rg -n 'unit_kind|64|256|prereg|tests_file' bonsai_interp/graph/contrib.py\"","aggregated_output":"cac519d2ec2789c16c6afcfa1a555d52fa23c53a Pre-register sweep tests\n1e96f8f278df56e40b4d0f477c502b32e697c4a9 Sweep round 9 papercuts: play run prints the @2 numbers from the recorded values the rule judges (it printed AUROC 0.91 for a 0.898 fail); play fill fills every drawn tests file from one JSON plan (LF endings, documented optional keys, reference list removed); draw's output is short\n# Graph schema\r\n\r\n```\r\ngraph/\r\n  contributions/<model>/L{L}_N{n}_{pos|neg}/\r\n      <id>.tests.json     pre-registration, committed FIRST       (contributors write this)\r\n      <id>.json           results, committed in a LATER commit    (written by `play run`)\r\n  neurons/<model>/L{L}_N{n}_{pos|neg}.json     derived record     (written by `fold`, never by hand)\r\n  edges.json                                   derived edge list\r\n  index.json                                   derived summary for the site and the game\r\n```\r\n\r\nThe model is `bonsai1` (Bonsai-8B, 1-bit): 36 layers, 12,288 neurons per layer, and two poles\r\nper neuron.\r\n\r\n## Contributions are append-only\r\n\r\nA contribution is never edited, renamed or deleted after it is merged; CI rejects any PR that\r\ndoes. A correction is a new contribution. Every record is recomputed from its neuron's\r\ncontributions in `(created, id)` order. This makes a merge **idempotent and non-destructive**:\r\nmerging the same contribution twice changes nothing, and new information never overwrites old.\r\n\r\n`<id>` is `YYYY-MM-DD-<github handle>-<random suffix>`. Core-team history uses `core-…` ids.\r\n\r\n### `<id>.tests.json` (the pre-registration)\r\n\r\n| Field | Meaning |\r\n|---|---|\r\n| `contribution`, `contributor`, `kind`, `neuron`, `protocol` | Who is testing which pole, and under which test protocol (e.g. `quick-8+8@1`) |\r\n| `neighbours` | `[{\"unit\": \"L12/N5397\", \"pole\": \"-\", \"label\": …, \"fire\": [8], \"quiet\": [8]}]` |\r\n| `qc` | For QC: `{\"verdict\": \"confirm\", \"dispute\" or \"refine\", \"label_under_test\": …}` |\r\n| `predictions`, `short`, `unit_kind`, `confidence`, `notes`, `roles`, `via` | Optional. They are copied into the results |\r\n\r\n### `<id>.json` (the results)\r\n\r\n| Field | Meaning |\r\n|---|---|\r\n| `id`, `kind`, `neuron`, `contributor`, `created` | `kind` is one of `interpret`, `qc`, `replicate` (a blind clean-room run) or `map` (edges only) |\r\n| `label` | For `interpret` and `qc` refine: the label that was tested |\r\n| `qc` | `{\"verdict\": \"confirm\" or \"dispute\" or \"refine\", \"label_under_test\": …}` |\r\n| `tests` | `[{protocol, tests_file, prereg_commit, author, …numbers…, per_sentence}]`. `counts_for_status: false` excludes a test from the status (used for model-written test sentences) |\r\n| `recipe` | `{\"toolchain_commit\": …, \"command\": …}` |\r\n| `edges` | `[{from, to, kind, weight, method}]` with full neuron ids |\r\n| `artifacts` | `[{name, url, sha256, bytes}]` in the library |\r\n| `short`, `unit_kind`, `confidence`, `depth`, `roles`, `via`, `examples`, `evidence`, `notes`, `verdict`, `summary`, `offshoots`, `lineage` | Optional |\r\n\r\n## Protocols are versioned\r\n\r\n`bonsai_interp/graph/protocols.py` maps each protocol to its pass rule:\r\n\r\n- `quick-8+8@1`: held if at least 5 of 8 sentences fire at 0.3 or more of the pole's corpus max,\r\n  and at most 1 near miss does.\r\n- `quick-8+8@2` (the default for new tests): held if the fire sentences rank above the near misses\r\n  (AUROC >= 0.90), the median fire sentence reaches 0.20 of the pole's corpus max, and at most 1\r\n  near miss reaches 0.30. It needs the per-sentence activations that `play run` records.\r\n- `held-out@1`\r\n- `cleanroom@1`\r\n\r\nA new pipeline adds a new version, such as `quick-8+8@2`. Old contributions keep the rule they\r\nwere made under. A test under a protocol the code doesn't know is kept and shown, but doesn't\r\nchange the status.\r\n\r\n## How a record is folded\r\n\r\nThe record keeps the earlier fields: `id`, `label`, `short`, `kind`, `status`, `depth`,\r\n`tests`, `label_history`, `examples`, `evidence`, `roles` and `contributors`. It adds\r\n`contributions`, `qc` counts and `replications`.\r\n\r\n| status | when |\r\n|---|---|\r\n| `unlabelled` | no contribution has tested a label yet |\r\n| `held` | the latest round of the current label held |\r\n| `contested` | the label held, but since it last changed, more QC tests have failed than held |\r\n| `failed` | no label has held yet; one or two failed rounds |\r\n| `unresolved` | no label has held after three failed rounds |\r\n| `dense` | a contribution set `unit_kind` to a dense kind |\r\n| `probed` | a full probe (`depth: full`) |\r\n| `replicated` | only blind replications so far |\r\n\r\nMore rules:\r\n\r\n- A failed round after a held label goes into `label_history` and does not replace the label. To\r\n  challenge a held label, use a QC `dispute`, or a QC `refine` with a better label.\r\n- `replicate` contributions never change the label.\r\n- For list fields, the record holds the union of all contributions, in order. For scalar fields,\r\n  the latest contribution wins.\r\n\r\n## Read API\r\n\r\nThe derived files are the survey's public, read-only API. There is no server and no account: read\r\nthem from a clone, or over HTTPS from the `main` branch (once the repository is public):\r\n\r\n```\r\nhttps://raw.githubusercontent.com/moridinamael/bonsai-interp/main/graph/index.json\r\nhttps://raw.githubusercontent.com/moridinamael/bonsai-interp/main/graph/neurons/bonsai1/L20_N12208_neg.json\r\nhttps://raw.githubusercontent.com/moridinamael/bonsai-interp/main/graph/edges.json\r\n```\r\n\r\nThey change only when the merge agent folds a merged contribution, so a commit hash pins a snapshot.\r\nNeuron ids are always `<model>/L<layer>/N<index><pole>`, e.g. `bonsai1/L20/N12208-`; record file names\r\nare `L<layer>_N<index>_<pos|neg>.json`.\r\n\r\n### `graph/index.json` (one object, about 1 KB per surveyed pole)\r\n\r\n| Field | Type | Meaning |\r\n|---|---|---|\r\n| `models` | `{model: {layers, neurons_per_layer}}` | The models the ids refer to (only `bonsai1`) |\r\n| `neurons` | `{id: entry}` | One entry per pole that has at least one contribution; poles not listed are unsurveyed |\r\n| `neurons[id].status` | string | One of the statuses in the table above |\r\n| `neurons[id].label`, `.short` | string or null | Current label (see \"How a record is folded\") and its short form |\r\n| `neurons[id].kind` | string or null | `unit_kind`, e.g. `dense / positional`, `token/lexical` |\r\n| `neurons[id].depth` | string | `quick` or `full` |\r\n| `neurons[id].qc` | `{confirm, dispute, refine}` | QC counts |\r\n| `neurons[id].n_contrib` | int | Number of contributions |\r\n| `neurons[id].replicated` | bool | Has a blind clean-room replication |\r\n| `neurons[id].contributors` | `[handle]` | In order of first contribution |\r\n| `neurons[id].t` | `[[protocol, outcome, n_fire, n_false_pos, author, contribution id]]` | Every test, oldest first. `outcome` is `held`, `failed`, `invalid` (fields missing for its protocol), `recorded` (a protocol the code does not score) or, for `cleanroom@1`, the blind verdict in words |\r\n| `neurons[id].history` | `[[label, outcome]]` | The last six labels tried |\r\n| `neurons[id].scrutiny` | `{level, name, test_rounds, sentences, contributors, qc}` | How much evidence there is, 0 `unexamined` to 5 `replicated` |\r\n| `edges` | `[[from id, to id, kind]]` | Every edge, without weights (those are in `edges.json`) |\r\n| `contributors` | `{handle: points}` | The scoreboard, highest first |\r\n\r\n### `graph/neurons/<model>/<pole>.json` (the full record)\r\n\r\nEvery field listed under \"How a record is folded\": `id`, `model`, `layer`, `index`, `pole`, `label`,\r\n`short`, `kind`, `status`, `depth`, `tests` (each with its `contribution` and `outcome`), `label_history`\r\n(`[contribution id, label, outcome]`), `examples`, `evidence`, `roles`, `contributors`, `contributions`,\r\n`qc`, `replications` and `scrutiny`, plus the latest value of each optional scalar (`verdict`, `summary`,\r\n`offshoots`, `lineage`). A record's `contributions` list names the files that produced it, so every\r\nnumber can be traced to a pre-registered test.\r\n\r\n### `graph/edges.json`\r\n\r\n`{\"edges\": [{from, to, kind, weight, method, contribution, …}]}`, sorted, with the latest measurement of\r\neach `(from, to, kind, method)`. `kind` is `feeds`, `reads`, `gates`, `co-fires` or an older free-text\r\nkind such as `feeds lateral`; for `feeds`, `weight` is the share of the target's activation lost when\r\nthe source is zeroed.\r\n\r\n### Not part of the API\r\n\r\n- `site/cards.json` and the cards embedded in the survey page are label-free summaries of the corpus\r\n  scan and the weights (top examples, density, regimes, direct logit effect) for surveyed neurons.\r\n  Their compact format may change with the page; for any neuron, run\r\n  `python -m bonsai_interp.graph.play card --neuron <id> --out card.json`.\r\n- `data/token_index_bonsai1.npz` (token -> poles, used by `play which --token`) is a local artifact\r\n  rebuilt from the scan on first use; it is never committed.\r\n\r\n### Versioning\r\n\r\nField names above are stable. Changes are **additive**: new fields may appear at any level, and\r\nreaders should ignore fields they don't know. Status values and test outcomes may gain new values;\r\ntreat an unknown one as \"not held\". A change that renames or removes a field, or changes a field's\r\nmeaning, adds a top-level `\"schema\"` integer to `index.json` (its absence means schema 1) and is\r\nannounced in this file. Protocols are versioned separately (see above), so a test's numbers are always\r\nread under the rule it was made under.\r\n\r\n## Commands\r\n\r\n```bash\r\npython -m bonsai_interp.graph.play new interpret --neuron bonsai1/L12/N5397- --handle you\r\npython -m bonsai_interp.graph.play run graph/contributions/bonsai1/L12_N5397_neg/<id>.tests.json\r\npython -m bonsai_interp.graph.fold            # preview the derived files locally (the merge agent commits them on main)\r\npython -m bonsai_interp.graph.validate        # what CI runs\r\npython -m bonsai_interp.graph.check_prereg --base origin/main\r\npython -m bonsai_interp.graph.play card --neuron bonsai1/L9/N3688+   # any neuron: examples, density, logit effect\r\npython -m bonsai_interp.graph.play which \"some text\"                 # reverse search; or --token \" nerve\"\r\n```\r\n27:MAX_FILE = 64 * 1024\n86:        tf = t.get(\"tests_file\")\n88:            say(f\"{rel}: tests[{i}] needs 'tests_file' (the pre-registration)\")\n90:            say(f\"{rel}: tests[{i}].tests_file does not exist: {tf}\")\n98:        if not (a.get(\"sha256\") and a.get(\"url\") and a.get(\"name\")):\n99:            say(f\"{rel}: each artifact needs name, url and sha256\")\n106:def check_tests_file(path: Path):\n","exit_code":0,"status":"completed"}}
runs\playtest\2026-10-18\sweep-10-codex.jsonl:53:{"type":"item.completed","item":{"id":"item_27","type":"command_execution","command":"\"C:\\\\windows\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe\" -Command 'Get-Content -Encoding utf8 bonsai_interp/graph/check_prereg.py | Select-Object -First 240'","aggregated_output":"\"\"\"Pull-request checks that need git history (CI runs this on every PR):\r\n\r\n  python -m bonsai_interp.graph.check_prereg --base origin/main\r\n\r\n1. Append-only: a PR may add files under graph/contributions/ but never modify, rename or delete one.\r\n2. Pre-registration order: every contribution results file (<id>.json) added by the PR names its\r\n   pre-registration (tests_file); that file must be on the base branch already or have been added\r\n   in an EARLIER commit of the PR, never in the same commit.\r\n   For legacy probe folders (probes/), result files must likewise follow a test file in that folder.\r\n3. Size: files added under graph/ are at most 64 KB each and 256 KB in total per PR (bulky material\r\n   belongs in the library; see DATA_POLICY.md). Nothing may be added under data/ or models/.\r\n\"\"\"\r\nimport argparse\r\nimport fnmatch\r\nimport json\r\nimport subprocess\r\nimport sys\r\nfrom pathlib import PurePosixPath\r\n\r\nTESTS = [\"*.tests.json\", \"*tests*.json\", \"holdout*.json\", \"*plan*.json\", \"*_test.json\", \"PREREG*.md\", \"*request*.json\"]\r\nRESULTS = [\"quick*.json\", \"*_quick*.json\", \"*results*.json\", \"*_out.json\", \"solo.json\", \"invert_*.json\"]\r\nMAX_FILE, MAX_TOTAL = 64 * 1024, 256 * 1024\r\n\r\n\r\ndef git(*a):\r\n    return subprocess.run([\"git\", *a], capture_output=True, text=True, encoding=\"utf-8\", check=True).stdout\r\n\r\n\r\ndef role(name):\r\n    if any(fnmatch.fnmatch(name, p) for p in TESTS):\r\n        return \"test\"\r\n    if any(fnmatch.fnmatch(name, p) for p in RESULTS):\r\n        return \"result\"\r\n    return None\r\n\r\n\r\ndef main():\r\n    ap = argparse.ArgumentParser()\r\n    ap.add_argument(\"--base\", default=\"origin/main\")\r\n    ap.add_argument(\"--allow-derived\", action=\"store_true\", help=\"for the merge agent's own fold commits\")\r\n    a = ap.parse_args()\r\n    commits = git(\"rev-list\", \"--reverse\", f\"{a.base}..HEAD\").split()\r\n    order = {c: i for i, c in enumerate(commits)}\r\n    first, problems = {}, []\r\n    for c in commits:\r\n        for line in git(\"show\", \"--name-status\", \"--format=\", c).splitlines():\r\n            st, *paths = line.split(\"\\t\")\r\n            derived = paths and paths[-1].startswith((\"graph/neurons/\", \"graph/edges.json\", \"graph/index.json\"))\r\n            if paths and (st.startswith((\"A\", \"C\")) or (st.startswith(\"M\") and derived)):  # a modified contribution must stay unrecorded here\r\n                first.setdefault(paths[-1], order[c])\r\n            for p in paths:\r\n                if p.startswith(\"graph/contributions/\") and (st.startswith((\"M\", \"D\", \"R\"))) and p not in first:\r\n                    problems.append(f\"{p}: contributions are append-only; it was {dict(M='modified', D='deleted', R='renamed').get(st[0])} in {c[:7]}\")\r\n    on_base = lambda p: subprocess.run([\"git\", \"cat-file\", \"-e\", f\"{a.base}:{p}\"], capture_output=True).returncode == 0\r\n    total = 0\r\n    tracked = set(git(\"ls-tree\", \"-r\", \"--name-only\", \"HEAD\").split(\"\\n\"))\r\n    for path, i in first.items():\r\n        p = PurePosixPath(path)\r\n        if path.startswith((\"graph/neurons/\", \"graph/edges.json\", \"graph/index.json\")) and not a.allow_derived:\r\n            problems.append(f\"{path}: derived file in a PR; drop it (git rm --cached) - the merge agent regenerates derived files on main\")\r\n        if path.startswith((\"data/\", \"models/\")):\r\n            problems.append(f\"{path}: nothing may be added under data/ or models/ (use the release or the library)\")\r\n        if path.startswith((\"graph/\", \"runs/\")) and p.suffix in (\".json\", \".jsonl\", \".md\", \".txt\"):\r\n            from bonsai_interp.graph.contrib import LOCAL_PATH\r\n            body = git(\"show\", f\"HEAD:{path}\") if path in tracked else \"\"\r\n            if LOCAL_PATH.search(body):\r\n                problems.append(f\"{path}: contains a local path (e.g. C:/Users/<name>/…); redact it to ~ (DATA_POLICY: no local paths)\")\r\n        if path.startswith(\"graph/\"):\r\n            size = len(git(\"show\", f\"HEAD:{path}\").encode(\"utf-8\")) if path in git(\"ls-tree\", \"-r\", \"--name-only\", \"HEAD\").split(\"\\n\") else 0\r\n            total += size\r\n            if size > MAX_FILE and path.startswith(\"graph/contributions/\"):\r\n                problems.append(f\"{path}: {size // 1024} KB is over the {MAX_FILE // 1024} KB per-file cap\")\r\n        if path.startswith(\"graph/contributions/\") and p.suffix == \".json\" and not p.name.endswith(\".tests.json\"):\r\n            c = json.loads(git(\"show\", f\"HEAD:{path}\"))\r\n            for t in c.get(\"tests\", []):\r\n                tf = t.get(\"tests_file\", \"\")\r\n                if on_base(tf) or (tf in first and first[tf] < i):\r\n                    continue\r\n                same = \" (added in the same commit as the results)\" if first.get(tf) == i else \"\"\r\n                problems.append(f\"{path}: pre-registration {tf!r} was not committed before the results{same}\")\r\n        elif path.startswith(\"probes/\") and role(p.name) == \"result\":\r\n            tests_here = [j for q, j in first.items() if PurePosixPath(q).parent == p.parent and role(PurePosixPath(q).name) == \"test\"]\r\n            base_tests = [q for q in git(\"ls-tree\", \"--name-only\", a.base, str(p.parent) + \"/\").split() if role(PurePosixPath(q).name) == \"test\"]\r\n            if not base_tests and not any(j < i for j in tests_here):\r\n                problems.append(f\"{path}: no test file committed before it in {p.parent}\")\r\n    if total > MAX_TOTAL:\r\n        problems.append(f\"this PR adds {total // 1024} KB under graph/, over the {MAX_TOTAL // 1024} KB cap\")\r\n    for m in problems:\r\n        print(\"PR CHECK\", m)\r\n    print(f\"{len(commits)} commits checked, {len(problems)} problems\")\r\n    sys.exit(1 if problems else 0)\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","exit_code":0,"status":"completed"}}
