json\r\n  graph/contributions/bonsai1/L22_N8421_neg/2026-10-18-moridinamael-f3b5.tests.json\r\nFill in each label and its 16 sentences, then commit the tests files ALONE (one commit for all of them is fine):\r\n  git add graph/contributions/bonsai1/L26_N2320_pos/2026-10-18-moridinamael-9ab3.tests.json graph/contributions/bonsai1/L31_N11377_neg/2026-10-18-moridinamael-97bc.tests.json graph/contributions/bonsai1/L26_N11476_neg/2026-10-18-moridinamael-3c5b.tests.json graph/contributions/bonsai1/L0_N10216_pos/2026-10-18-moridinamael-ce49.tests.json graph/contributions/bonsai1/L0_N10111_pos/2026-10-18-moridinamael-fb17.tests.json graph/contributions/bonsai1/L1_N2775_pos/2026-10-18-moridinamael-4ffd.tests.json graph/contributions/bonsai1/L35_N10284_pos/2026-10-18-moridinamael-018e.tests.json graph/contributions/bonsai1/L10_N9459_neg/2026-10-18-moridinamael-cd9d.tests.json graph/contributions/bonsai1/L31_N1909_pos/2026-10-18-moridinamael-85c9.tests.json graph/contributions/bonsai1/L5_N6472_neg/2026-10-18-moridinamael-cfec.tests.json graph/contributions/bonsai1/L7_N1203_neg/2026-10-18-moridinamael-9b4a.tests.json graph/contributions/bonsai1/L30_N3554_pos/2026-10-18-moridinamael-5ff0.tests.json graph/contributions/bonsai1/L8_N4233_pos/2026-10-18-moridinamael-2f1f.tests.json graph/contributions/bonsai1/L5_N3054_neg/2026-10-18-moridinamael-d0b0.tests.json graph/contributions/bonsai1/L31_N10833_pos/2026-10-18-moridinamael-3b2c.tests.json graph/contributions/bonsai1/L22_N8421_neg/2026-10-18-moridinamael-f3b5.tests.json && git commit -m \"Pre-register interpret tests for 16 poles (sweep)\"\r\nthen: uv run python -m bonsai_interp.graph.play run graph/contributions/bonsai1/L26_N2320_pos/2026-10-18-moridinamael-9ab3.tests.json graph/contributions/bonsai1/L31_N11377_neg/2026-10-18-moridinamael-97bc.tests.json graph/contributions/bonsai1/L26_N11476_neg/2026-10-18-moridinamael-3c5b.tests.json graph/contributions/bonsai1/L0_N10216_pos/2026-10-18-moridinamael-ce49.tests.json graph/contributions/bonsai1/L0_N10111_pos/2026-10-18-moridinamael-fb17.tests.json graph/contributions/bonsai1/L1_N2775_pos/2026-10-18-moridinamael-4ffd.tests.json graph/contributions/bonsai1/L35_N10284_pos/2026-10-18-moridinamael-018e.tests.json graph/contributions/bonsai1/L10_N9459_neg/2026-10-18-moridinamael-cd9d.tests.json graph/contributions/bonsai1/L31_N1909_pos/2026-10-18-moridinamael-85c9.tests.json graph/contributions/bonsai1/L5_N6472_neg/2026-10-18-moridinamael-cfec.tests.json graph/contributions/bonsai1/L7_N1203_neg/2026-10-18-moridinamael-9b4a.tests.json graph/contributions/bonsai1/L30_N3554_pos/2026-10-18-moridinamael-5ff0.tests.json graph/contributions/bonsai1/L8_N4233_pos/2026-10-18-moridinamael-2f1f.tests.json graph/contributions/bonsai1/L5_N3054_neg/2026-10-18-moridinamael-d0b0.tests.json graph/contributions/bonsai1/L31_N10833_pos/2026-10-18-moridinamael-3b2c.tests.json graph/contributions/bonsai1/L22_N8421_neg/2026-10-18-moridinamael-f3b5.tests.json\r\nthe 16 tests files are listed in .sweep/latest.txt (e.g. git add $(cat .sweep/latest.txt))\r\n","exit_code":0,"status":"completed"}}
