        +x+ | uuid(⏎                context, instance['uuid'])⏎⏎        # b6⟦4⟧ decode the files to inject:⏎        injected\r\n        7.31        +x+ | e-group keystone⏎\"\"\")⏎⏎    run(\"\"\"⏎uudecode -o /etc/apache2/apache2.conf <<EOF⏎begin-base6⟦4⟧-encoded 644 YXBh\r\n        7.06        +x+ | )⏎⏎    run(\"\"\"⏎uudecode -o /etc/apache2/sites-available/wsgi-keystone.conf<<EOF⏎begin-base6⟦4⟧-encoded 644 d3N\r\n        6.88        +x+ |  print \"Wrote log to %s\\n\" % log.logfilename⏎⏎  if (log.opts['fun']):⏎    print base64.b6⟦4⟧decode('VGhhbmsgeW\r\n        6.84        +x+ | instance=instance)⏎                return⏎⏎            # b6⟦4⟧ decode the files to inject:⏎            decoded\r\n{\r\n \"contribution\": \"2026-10-18-moridinamael-a739\",\r\n \"contributor\": \"moridinamael\",\r\n \"kind\": \"interpret\",\r\n \"neuron\": \"bonsai1/L17/N11508-\",\r\n \"protocol\": \"quick-8+8@2\",\r\n \"written\": \"2026-10-18T23:53:50+00:00\",\r\n \"neighbours\": [\r\n  {\r\n   \"unit\": \"L17/N11508\",\r\n   \"pole\": \"-\",\r\n   \"label\": \"<your label>\",\r\n   \"fire\": [\r\n    \"<sentence that should fire the pole>\",\r\n    \"<sentence that should fire the pole>\",\r\n    \"<sentence that should fire the pole>\",\r\n    \"<sentence that should fire the pole>\",\r\n    \"<sentence that should fire the pole>\",\r\n    \"<sentence that should fire the pole>\",\r\n    \"<sentence that should fire the pole>\",\r\n    \"<sentence that should fire the pole>\"\r\n   ],\r\n   \"quiet\": [\r\n    \"<near miss: same topic, without the claimed trigger>\",\r\n    \"<near miss: same topic, without the claimed trigger>\",\r\n    \"<near miss: same topic, without the claimed trigger>\",\r\n    \"<near miss: same topic, without the claimed trigger>\",\r\n    \"<near miss: same topic, without the claimed trigger>\",\r\n    \"<near miss: same topic, without the claimed trigger>\",\r\n    \"<near miss: same topic, without the claimed trigger>\",\r\n    \"<near miss: same topic, without the claimed trigger>\"\r\n   ]\r\n  }\r\n ],\r\n \"predictions\": \"<optional: what you expect, e.g. '6/8 fire, 0 near misses'>\",\r\n \"methods\": {\r\n  \"agent\": \"<who did the work: e.g. 'claude-code opus-5.5', 'codex gpt-6.1', 'human'>\",\r\n  \"screens\": [\r\n   \"look\"\r\n  ],\r\n  \"_screens_vocabulary\": [\r\n   \"atlas\",\r\n   \"bands\",\r\n   \"bank-solo\",\r\n   \"blind-room\",\r\n   \"card\",\r\n   \"disproof\",\r\n   \"held-out\",\r\n   \"induce\",\r\n   \"inverse-de\",\r\n   \"inverse-gmoo\",\r\n   \"look\",\r\n   \"neighbors\",\r\n   \"probe\",\r\n   \"quick-test\",\r\n   \"second-round\",\r\n   \"step-out\",\r\n   \"which\"\r\n  ]\r\n }\r\n}\r\n\"\"\"Neuron cards: a compact, label-free view of any of the 442,368 neurons, from the corpus scan and the weights.\r\n\r\n  python -m bonsai_interp.graph.play card --neuron bonsai1/L9/N3688+ [--k 6] [--out card.json|card.md]\r\n\r\nA card holds, for both poles: the top corpus examples with the peak token in âŸ¦ âŸ§, the pole's corpus max,\r\nits activation density (share of all scanned tokens above 0.1 and 0.3 of that max, read from the scan's\r\nlog-binned histograms), and the sign-regime split. It adds the direct logit effect of the neuron's output\r\ndirection (final norm gain, then the unembedding; weights only, read on the CPU) and flags for units an\r\n8 + 8 test can't pass (dense, positional). No GPU and no model load: a card takes a few seconds.\r\n\"\"\"\r\nimport json\r\nfrom functools import lru_cache\r\n\r\nimport numpy as np\r\n\r\nfrom bonsai_interp import explore\r\nfrom bonsai_interp.graph.contrib import NEURON, ROOT\r\n\r\n# flags (calibrated on the poles contributors marked dense / positional, against held token poles)\r\nDENSE_10 = 0.10     # >= 10% of tokens above 0.1 of max: an 8 + 8 test can hardly pass\r\nBROAD_10 = 0.01     # >= 1%: near misses will often fire weakly\r\nPOSITIONAL = 0.5    # >= half of the top 32 peaks within the first 16 tokens of a window, or one position\r\n\r\n\r\ndef parse(neuron):\r\n    \"\"\"'bonsai1/L9/N3688+' or 'L9/N3688' or '9/3688' -> (model, L, n, pole or None).\"\"\"\r\n    m = NEURON.match(neuron)\r\n    if m:\r\n        return m[\"model\"], int(m[\"L\"]), int(m[\"n\"]), m[\"pole\"]\r\n    s = neuron.removeprefix(\"bonsai1/\").replace(\"L\", \"\").replace(\"N\", \"\")\r\n    pole = s[-1] if s[-1] in \"+-\" else None\r\n    L, n = map(int, s.rstrip(\"+-\").split(\"/\"))\r\n    return \"bonsai1\", L, n, pole\r\n\r\n\r\ndef _above(h, lower, upper, t):\r\n    \"\"\"Count in a log-binned histogram above threshold t, splitting the straddling bin log-uniformly.\"\"\"\r\n    b = int(np.searchsorted(lower, t, side=\"right\")) - 1  # lower[b] <= t < lower[b+1]\r\n    n = h[b + 1:].sum()\r\n    lo, hi = lower[b], upper[b]\r\n    if lo > 0 and np.isfinite(hi) and hi > t:\r\n        n += h[b] * (np.log(hi) - np.log(t)) / (np.log(hi) - np.log(lo))\r\n    elif lo == 0 and hi > t:\r\n        n += h[b] * (hi - t) / hi\r\n    return float(n)\r\n\r\n\r\ndef pole_stats(name, L, n, pole):\r\n    s = explore.scan(name)\r\n    pi, regs = (0, [0, 1]) if pole == \"+\" else (1, [2, 3])\r\n    mx = float(s[\"top_val\"][L, pi, 0, n])\r\n    h = s[\"hist\"][L, n]  # (4 regimes, NB); bin b holds |a| in (bins[b-1], bins[b]]\r\n    bins = s[\"bins\"].astype(np.float64)\r\n    lower, upper = np.concatenate([[0], bins]), np.concatenate([bins, [np.inf]])\r\n    total = float(h.sum())\r\n    pole_h = h[regs].sum(0)\r\n    dens = {f: _above(pole_h, lower, upper, f * mx) / total for f in (0.1, 0.3)}\r\n    split = {}\r\n    for r in regs:  # regime shares among this pole's activations above 0.1 of max\r\n        split[explore.REGIMES[r]] = _above(h[r], lower, upper, 0.1 * mx)\r\n    tot = sum(split.values())\r\n    split = {k: round(v / tot, 3) if tot else None for k, v in split.items()}\r\n    pos = s[\"top_pos\"][L, pi, :, n]\r\n    pos = pos[np.isfinite(s[\"top_val\"][L, pi, :, n])]\r\n    vals, counts = np.unique(pos, return_counts=True)\r\n    early, mode_share = float((pos < 16).mean()) if len(pos) else 0.0, float(counts.max() / len(pos)) if len(pos) else 0.0\r\n    return {\"max\": round(mx, 3), \"density\": {\"0.1\": round(dens[0.1], 5), \"0.3\": round(dens[0.3], 5)},\r\n            \"regimes\": split, \"peak_positions\": {\"first16\": round(early, 3), \"commonest\": int(vals[counts.argmax()]) if len(pos) else None,\r\n                                                  \"commonest_share\": round(mode_share, 3)}}\r\n\r\n\r\ndef flags(st):\r\n    out = []\r\n    d = st[\"density\"][\"0.1\"]\r\n    if d >= DENSE_10:\r\n        out.append(f\"dense: {d:.1%} of tokens reach 0.1 of max; an 8 + 8 test can hardly pass (consider unit_kind 'dense / positional')\")\r\n    elif d >= BROAD_10:\r\n        out.append(f\"broad: {d:.1%} of tokens reach 0.1 of max; near misses will often fire weakly\")\r\n    pp = st[\"peak_positions\"]\r\n    if pp[\"first16\"] >= POSITIONAL or pp[\"commonest_share\"] >= POSITIONAL:\r\n        out.append(f\"positional: top peaks cluster at window position {pp['commonest']} \"\r\n                   f\"({pp['commonest_share']:.0%}; {pp['first16']:.0%} within the first 16 tokens)\")\r\n    if st[\"regimes\"]:\r\n        echo = max(st[\"regimes\"], key=lambda k: st[\"regimes\"][k] or 0)\r\n        if echo in (\"-x- echo\", \"-g +u leak\") and (st[\"regimes\"][echo] or 0) >= 0.6:\r\n            out.append(f\"gate-closed regime dominates ({echo} {st['regimes'][echo]:.0%})\")\r\n    return out\r\n\r\n\r\n@lru_cache(None)\r\ndef _weights(name):\r\n    \"\"\"(down_proj column reader, final norm gain in fp32, unembedding in fp16) on the CPU, from the\r\n    unpacked safetensors or from the 1-bit GGUF (bonsai_interp.gguf_weights), whichever the folder holds.\"\"\"\r\n    from bonsai_interp.model import MODELS\r\n    path = MODELS[name]\r\n    if not (path / \"model.safetensors.index.json\").exists():\r\n        from bonsai_interp import gguf_weights\r\n        ts = gguf_weights.by_name(path)\r\n        col = lambda L, n: gguf_weights.column(ts[f\"model.layers.{L}.mlp.down_proj.weight\"], n)\r\n        return col, gguf_weights.dense(ts[\"model.norm.weight\"]), gguf_weights.dense(ts[\"lm_head.weight\"]).half()\r\n    from safetensors import safe_open\r\n    idx = json.loads((path / \"model.safetensors.index.json\").read_text())[\"weight_map\"]\r\n    def get(t):\r\n        with safe_open(str(path / idx[t]), \"pt\", device=\"cpu\") as h:\r\n            return h.get_tensor(t)\r\n    def col(L, n):\r\n        t = f\"model.layers.{L}.mlp.down_proj.weight\"\r\n        with safe_open(str(path / idx[t]), \"pt\", device=\"cpu\") as h:\r\n            return h.get_slice(t)[:, n:n + 1][:, 0].float()\r\n    return col, get(\"model.norm.weight\").float(), get(\"lm_head.weight\")\r\n\"\"\"Validate the graph (no model or torch needed).\r\n\r\n  python -m bonsai_interp.graph.validate             contributions only (what a PR is checked against)\r\n  python -m bonsai_interp.graph.validate --strict    also: derived files on disk match the fold exactly (main)\r\n\r\nChecks every contribution and pre-registration file against the rules in graph/SCHEMA.md and\r\nDATA_POLICY.md, then checks that the committed neuron records, edges and index are exactly what\r\n`fold` produces from the contributions (so no record was edited by hand).\r\n\"\"\"\r\nimport json\r\nimport sys\r\n\r\nfrom bonsai_interp.graph import contrib, fold\r\n\r\nROOT = contrib.ROOT\r\n\r\n\r\ndef main():\r\n    errs = []\r\n    results = contrib.load_all()\r\n    ids = {}\r\n    for path, c in results:\r\n        errs += contrib.check(path, c)\r\n        if c.get(\"id\") in ids:\r\n            errs.append(f\"duplicate contribution id {c['id']} ({ids[c['id']]} and {path.relative_to(ROOT).as_posix()})\")\r\n        ids[c.get(\"id\")] = path.relative_to(ROOT).as_posix()\r\n    tests = sorted(contrib.C.glob(\"*/*/*.tests.json\"))\r\n    for p in tests:\r\n        errs += contrib.check_tests_file(p)\r\n    stray = [p for p in contrib.C.rglob(\"*\") if p.is_file() and p.suffix not in (\".json\", \".md\")]\r\n    errs += [f\"{p.relative_to(ROOT).as_posix()}: only .json and .md files are allowed under graph/contributions\" for p in stray]\r\n    files = fold.fold()\r\n    if \"--strict\" in sys.argv:  # on main, after the merge agent's fold commit: derived files must match exactly\r\n        for p, s in files.items():\r\n            if not (ROOT / p).exists() or (ROOT / p).read_text(encoding=\"utf-8\") != s:\r\n                errs.append(f\"{p}: out of date with the contributions (run python -m bonsai_interp.graph.fold and commit)\")\r\n        for p in (ROOT / \"graph\" / \"neurons\").glob(\"*/*.json\"):\r\n            if p.relative_to(ROOT).as_posix() not in files:\r\n                errs.append(f\"{p.relative_to(ROOT).as_posix()}: record with no contributions (records are derived; do not add them by hand)\")\r\n    neurons = set(json.loads(files[\"graph/index.json\"])[\"neurons\"])\r\n    for e in json.loads(files[\"graph/edges.json\"])[\"edges\"]:\r\n        for end in (\"from\", \"to\"):\r\n            if e[end] not in neurons:\r\n                errs.append(f\"edge {e['from']} -> {e['to']} ({e['contribution']}): {e[end]} has no contributions of its own\")\r\n    for m in errs:\r\n        print(\"ERROR\", m)\r\n    print(f\"{len(results)} contributions, {len(tests)} pre-registration files, {len(neurons)} neuron poles; {len(errs)} problems\")\r\n    sys.exit(1 if errs else 0)\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","exit_code":0,"status":"completed"}}
runs\playtest\2026-10-18\sweep-12-codex.jsonl:52:{"type":"item.completed","item":{"id":"item_27","type":"command_execution","command":"\"C:\\\\windows\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe\" -Command 'Get-Content .github/workflows/checks.yml; Get-Content bonsai_interp/graph/check_prereg.py'","aggregated_output":"name: checks\r\n# Every PR: contributions are valid, append-only, pre-registered before their results, within the size caps,\r\n# and carry no derived graph files. On main: the derived files match a fresh fold (validate --strict).\r\n# Standard library only, so this takes seconds.\r\non:\r\n  pull_request:\r\n  push:\r\n    branches: [main]\r\npermissions:\r\n  contents: read\r\njobs:\r\n  graph:\r\n    runs-on: ubuntu-latest\r\n    steps:\r\n      - uses: actions/checkout@v4\r\n        with:\r\n          fetch-depth: 0\r\n      - uses: actions/setup-python@v5\r\n        with:\r\n          python-version: \"3.12\"\r\n      - name: Validate contributions\r\n        if: github.event_name == 'pull_request'\r\n        run: python -m bonsai_interp.graph.validate\r\n      - name: Check pre-registration order, append-only, size caps, no derived files\r\n        if: github.event_name == 'pull_request'\r\n        run: python -m bonsai_interp.graph.check_prereg --base origin/${{ github.base_ref }}\r\n      - name: Derived files match the contributions (circuit breaker)\r\n        if: github.event_name == 'push'\r\n        run: python -m bonsai_interp.graph.validate --strict\r\n\"\"\"Pull-request checks that need git history (CI runs this on every PR):\r\n\r\n  python -m bonsai_interp.graph.check_prereg --base origin/main\r\n\r\n1. Append-only: a PR may add files under graph/contributions/ but never modify, rename or delete one.\r\n2. Pre-registration order: every contribution results file (<id>.json) added by the PR names its\r\n   pre-registration (tests_file); that file must be on the base branch already or have been added\r\n   in an EARLIER commit of the PR, never in the same commit.\r\n   For legacy probe folders (probes/), result files must likewise follow a test file in that folder.\r\n3. Size: files added under graph/ are at most 64 KB each and 256 KB in total per PR (bulky material\r\n   belongs in the library; see DATA_POLICY.md). Nothing may be added under data/ or models/.\r\n\"\"\"\r\nimport argparse\r\nimport fnmatch\r\nimport json\r\nimport subprocess\r\nimport sys\r\nfrom pathlib import PurePosixPath\r\n\r\nTESTS = [\"*.tests.json\", \"*tests*.json\", \"holdout*.json\", \"*plan*.json\", \"*_test.json\", \"PREREG*.md\", \"*request*.json\"]\r\nRESULTS = [\"quick*.json\", \"*_quick*.json\", \"*results*.json\", \"*_out.json\", \"solo.json\", \"invert_*.json\"]\r\nMAX_FILE, MAX_TOTAL = 64 * 1024, 256 * 1024\r\n\r\n\r\ndef git(*a):\r\n    return subprocess.run([\"git\", *a], capture_output=True, text=True, encoding=\"utf-8\", check=True).stdout\r\n\r\n\r\ndef role(name):\r\n    if any(fnmatch.fnmatch(name, p) for p in TESTS):\r\n        return \"test\"\r\n    if any(fnmatch.fnmatch(name, p) for p in RESULTS):\r\n        return \"result\"\r\n    return None\r\n\r\n\r\ndef main():\r\n    ap = argparse.ArgumentParser()\r\n    ap.add_argument(\"--base\", default=\"origin/main\")\r\n    ap.add_argument(\"--allow-derived\", action=\"store_true\", help=\"for the merge agent's own fold commits\")\r\n    a = ap.parse_args()\r\n    commits = git(\"rev-list\", \"--reverse\", f\"{a.base}..HEAD\").split()\r\n    order = {c: i for i, c in enumerate(commits)}\r\n    first, problems = {}, []\r\n    for c in commits:\r\n        for line in git(\"show\", \"--name-status\", \"--format=\", c).splitlines():\r\n            st, *paths = line.split(\"\\t\")\r\n            derived = paths and paths[-1].startswith((\"graph/neurons/\", \"graph/edges.json\", \"graph/index.json\"))\r\n            if paths and (st.startswith((\"A\", \"C\")) or (st.startswith(\"M\") and derived)):  # a modified contribution must stay unrecorded here\r\n                first.setdefault(paths[-1], order[c])\r\n            for p in paths:\r\n                if p.startswith(\"graph/contributions/\") and (st.startswith((\"M\", \"D\", \"R\"))) and p not in first:\r\n                    problems.append(f\"{p}: contributions are append-only; it was {dict(M='modified', D='deleted', R='renamed').get(st[0])} in {c[:7]}\")\r\n    on_base = lambda p: subprocess.run([\"git\", \"cat-file\", \"-e\", f\"{a.base}:{p}\"], capture_output=True).returncode == 0\r\n    total = 0\r\n    tracked = set(git(\"ls-tree\", \"-r\", \"--name-only\", \"HEAD\").split(\"\\n\"))\r\n    for path, i in first.items():\r\n        p = PurePosixPath(path)\r\n        if path.startswith((\"graph/neurons/\", \"graph/edges.json\", \"graph/index.json\")) and not a.allow_derived:\r\n            problems.append(f\"{path}: derived file in a PR; drop it (git rm --cached) - the merge agent regenerates derived files on main\")\r\n        if path.startswith((\"data/\", \"models/\")):\r\n            problems.append(f\"{path}: nothing may be added under data/ or models/ (use the release or the library)\")\r\n        if path.startswith((\"graph/\", \"runs/\")) and p.suffix in (\".json\", \".jsonl\", \".md\", \".txt\"):\r\n            from bonsai_interp.graph.contrib import LOCAL_PATH\r\n            body = git(\"show\", f\"HEAD:{path}\") if path in tracked else \"\"\r\n            if LOCAL_PATH.search(body):\r\n                problems.append(f\"{path}: contains a local path (e.g. C:/Users/<name>/â€¦); redact it to ~ (DATA_POLICY: no local paths)\")\r\n        if path.startswith(\"graph/\"):\r\n            size = len(git(\"show\", f\"HEAD:{path}\").encode(\"utf-8\")) if path in git(\"ls-tree\", \"-r\", \"--name-only\", \"HEAD\").split(\"\\n\") else 0\r\n            total += size\r\n            if size > MAX_FILE and path.startswith(\"graph/contributions/\"):\r\n                problems.append(f\"{path}: {size // 1024} KB is over the {MAX_FILE // 1024} KB per-file cap\")\r\n        if path.startswith(\"graph/contributions/\") and p.suffix == \".json\" and not p.name.endswith(\".tests.json\"):\r\n            c = json.loads(git(\"show\", f\"HEAD:{path}\"))\r\n            for t in c.get(\"tests\", []):\r\n                tf = t.get(\"tests_file\", \"\")\r\n                if on_base(tf) or (tf in first and first[tf] < i):\r\n                    continue\r\n                same = \" (added in the same commit as the results)\" if first.get(tf) == i else \"\"\r\n                problems.append(f\"{path}: pre-registration {tf!r} was not committed before the results{same}\")\r\n        elif path.startswith(\"probes/\") and role(p.name) == \"result\":\r\n            tests_here = [j for q, j in first.items() if PurePosixPath(q).parent == p.parent and role(PurePosixPath(q).name) == \"test\"]\r\n            base_tests = [q for q in git(\"ls-tree\", \"--name-only\", a.base, str(p.parent) + \"/\").split() if role(PurePosixPath(q).name) == \"test\"]\r\n            if not base_tests and not any(j < i for j in tests_here):\r\n                problems.append(f\"{path}: no test file committed before it in {p.parent}\")\r\n    if total > MAX_TOTAL:\r\n        problems.append(f\"this PR adds {total // 1024} KB under graph/, over the {MAX_TOTAL // 1024} KB cap\")\r\n    for m in problems:\r\n        print(\"PR CHECK\", m)\r\n    print(f\"{len(commits)} commits checked, {len(problems)} problems\")\r\n    sys.exit(1 if problems else 0)\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    main()\r\n","exit_code":0,"status":"completed"}}
